INSERT INTO "public"."ltr_kalkulacje" ("id", "numer_kalkulacji", "status", "stan_json", "dane_pojazdu", "cena_netto", "created_at", "updated_at") VALUES ('0e3028cb-5496-4a8f-9f25-68825e7aa518', 'KALK/2026/03/8FAFBF', 'szkic_vertex', '{"brand": "SKODA", "model": "Superb Combi", "toggles": {"gps_required": true, "replacement_car": true, "hook_installation": true, "include_servicing": true, "express_pays_insurance": true}, "discount": {"active_final_price": 183388, "active_discount_pct": 24}, "is_metalic": true, "vehicle_id": "b9ebfe45-4db0-4f5e-ab03-38c664a3071c", "tire_params": {"tire_class": "Premium", "rim_diameter": 17, "tire_count_mode": "auto", "tire_cost_correction": 0, "tire_cost_correction_enabled": true}, "card_summary": {"fuel": "Diesel", "wheels": "17", "power_hp": 193, "emissions": "CO2: 152 g/km, Zużycie paliwa: 5,8 l/100km", "base_price": "212 350 PLN brutto", "body_style": "Kombi", "drive_type": "Napęd AWD", "powertrain": "2.0 TDI 193 KM", "trim_level": "Selection", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 212350, "total": 241300, "options": 28950}}, "power_range": "MID (131 - 200 KM)", "total_price": "241 300 PLN brutto", "has_tow_hook": true, "paid_options": [{"name": "Żółty Ice Tea Metalizowany", "price": "3500 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Obręcze kół ze stopów lekkich 7,5J x 17\" Alrakis Aero, czarne z połyskiem", "price": "650 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Infotainment", "price": "5000 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Climate", "price": "2600 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Drive Plus", "price": "5400 PLN brutto", "category": "Fabryczn