INSERT INTO "public"."ltr_kalkulacje" ("id", "numer_kalkulacji", "status", "stan_json", "dane_pojazdu", "cena_netto", "created_at", "updated_at") VALUES ('100192c5-3d58-4a71-89e1-c8ad2559c8cb', 'KALK/2026/03/E9BA52', 'szkic_vertex', '{"brand": "Volkswagen", "model": "Crafter Furgon", "toggles": {"gps_required": true, "replacement_car": true, "hook_installation": true, "include_servicing": true, "express_pays_insurance": true}, "discount": {"active_final_price": 161612.8, "active_discount_pct": 36}, "is_metalic": false, "vehicle_id": "06118cde-6f53-445e-a775-74352d217d1d", "tire_params": {"tire_class": "Wzmocnione Medium", "rim_diameter": 16, "tire_count_mode": "auto", "tire_cost_correction": 0, "tire_cost_correction_enabled": true}, "card_summary": {"fuel": "Diesel", "wheels": "16", "power_hp": 177, "emissions": "263 g/km, 10 l/100km (WLTP, cykl mieszany)", "base_price": "204090,00 PLN netto", "body_style": "Furgon", "drive_type": "Napęd AWD", "powertrain": "2.0 SCR 177 KM 4MOTION", "trim_level": "Brak", "_validation": {"summary": {"details": "Suma ceny bazowej i opcji znacząco różni się od podanej ceny całkowitej. Dodatkowo, cena bazowa jest wyższa niż cena całkowita, co sugeruje zamianę tych pól.", "verdict": "Cennik zawiera poważne błędy arytmetyczne, wskazujące na nieprawidłowe przypisanie wartości cenowych.", "confidence": "LOW", "suggestions": ["Zweryfikuj i popraw wartości w polach ''cena bazowa'' oraz ''cena całkowita'', prawdopodobnie zostały one zamienione miejscami.", "Upewnij się, że cena całkowita jest sumą ceny bazowej i wszystkich opcji."]}, "is_valid": false, "warnings": [{"rule": "BASE_PLUS_OPTIONS_VS_TOTAL", "actual": 161612.8, "message": "baza(204090) + opcje(48430) = 252520, ale total = 161613 (Δ 90907 / 36.0%)", "diff_pct": 36, "expected": 252520, "severity": "ERROR"}, {"rule": "BASE_TOTAL_SWAPPED", "actual": 204090, "message": "base(204090) > total(161613) — kolejność cen może być odwrócona", "expected": 161612.8, "severity": "WARNING"}], "pars