INSERT INTO "public"."ltr_kalkulacje" ("id", "numer_kalkulacji", "status", "stan_json", "dane_pojazdu", "cena_netto", "created_at", "updated_at") VALUES ('269fbde6-96cf-4723-bccc-550fb5bc7a66', 'KALK/2026/03/4E19A6', 'szkic_vertex', '{"brand": "SKODA", "model": "Fabia", "toggles": {"gps_required": true, "replacement_car": true, "hook_installation": false, "include_servicing": true, "express_pays_insurance": true}, "discount": {"active_final_price": 65058, "active_discount_pct": 16}, "is_metalic": true, "vehicle_id": "9253346a-7757-464f-9f41-6cef924f6e3c", "tire_params": {"tire_class": "Medium", "rim_diameter": 15, "tire_count_mode": "auto", "tire_cost_correction": 0, "tire_cost_correction_enabled": true}, "card_summary": {"fuel": "Benzyna", "wheels": "15", "power_hp": 80, "emissions": "Emisja CO2 w cyklu mieszanym 117 g/km / Zużycie paliwa/energii w cyklu mieszanym 5,1 l/100km", "base_price": "73450 PLN brutto", "body_style": "Hatchback", "drive_type": "Napęd FWD", "powertrain": "1.0 MPI 80 KM", "trim_level": "Essence", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 73450, "total": 77450, "options": 4000}}, "power_range": "LOW (do 130 KM)", "total_price": "77450 PLN brutto", "has_tow_hook": null, "paid_options": [{"name": "Szary Graphite Metalizowany", "price": "2400 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Technology", "price": "1600 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Manualna", "_price_domain": "brutto", "options_price": "4000 PLN brutto", "vehicle_class": "Osobowy", "exterior_color": "Szary Graphite Metalizowany", "engine_capacity": "1.0", "engine_category": "Benzyna (PB)", "is_metalic_paint": true, "utility_features": [], "service_equipment": null, "engine_designation": "MPI", "standard_equipment": ["Sygnalizacja ostrzegawcza niezapiętych pasów bezpieczeństwa z przodu i z tyłu", "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania z Pedestrian Monitor", "Lane Assist - asystent pasa ruchu", "Easy Light Assist - czujnik zmierzchu", "Czujnik parkowania z tyłu", "Rozpoznawanie znaków drogowych", "Driver Alert - funkcja wykrywania zmęczenia kierowcy", "Hill Hold Control - system wspomagania ruszania pod wzniesienia", "Bluetooth", "Cyfrowy zestaw wskaźników Digital Display", "Radio (ekran 8\", dwa gniazda USB-C)", "Klimatyzacja manualna", "TPM - sygnalizacja spadku ciśnienia w oponach", "Ogranicznik prędkości", "Reflektory LED Basic z przodu", "Reflektory przeciwmgłowe z przodu", "Elektrycznie sterowane szyby przednie", "Lusterka boczne w kolorze nadwozia", "Elektrycznie sterowane i podgrzewane lusterka boczne", "Chromowana ramka grilla", "Stalowe obręcze kół z osłonami Calisto Aero 5,5J x 15\"", "Lusterko wsteczne, przyciemnione", "Dwuramienna kierownica z tworzywa sztucznego", "Fotel kierowcy regulowany na wysokość", "Podłokietnik z przodu", "Dywaniki tekstylne", "Przestrzeń bagażowa z oświetleniem (1 lampka)"], "financial_reasoning": "Na podstawie sekcji ''pricing_summary'' zidentyfikowano następujące kwoty: ''Twoja konfiguracja'' (cena bazowa) za 73 450 zł, ''Wybrane wyposażenie opcjonalne i usługi'' za 4 000 zł oraz ''Cena widocznej konfiguracji'' (cena całkowita) za 77 450 zł. W sekcji ''selected_equipment'' wyszczególniono opcje płatne: ''Szary Graphite Metalizowany'' za 2 400 zł i ''Pakiet Technology'' za 1 600 zł. Sprawdzenie matematyczne: suma opcji 2 400 zł + 1 600 zł = 4 000 zł, co zgadza się z podsumowaniem. Cena bazowa (73 450 zł) + suma opcji (4 000 zł) = 77 450 zł, co zgadza się z ceną całkowitą. W dokumencie znajduje się informacja ''Podane ceny obejmują podatek VAT (23%)'', co jednoznacznie wskazuje, że wszystkie kwoty są brutto. Nie zidentyfikowano żadnych rabatów.", "suggested_discount_pct": 16, "is_current_year_vehicle": true, "suggested_discount_source": "Dopasowano do modelu SKODA Fabia w wersji Essence na podstawie dokładnego dopasowania marki, modelu, wersji wyposażenia oraz zgodności kodu konfiguracji (PJ3B**).", "suggested_discount_confidence": 98}, "digital_twin": {"metadata": {"document_type": "Oferta na samochód"}, "tire_labels": {"tires": [{"code": "2259623", "page": 7, "size": "185/65 R15", "class": "C1", "model": "ES31", "specs": "185/65R15 88 H", "wet_grip": "A", "manufacturer": "Kumho", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "noise_level_db": "69", "fuel_efficiency": "A", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/aVYbcOK7haiqkYbYHWp4vQ==", "noise_level_class": "B"}, {"code": "0314699", "page": 7, "size": "185/65 R15", "class": "C1", "model": null, "specs": "185/65 R 15 88 H", "wet_grip": "B", "manufacturer": "Continental", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "noise_level_db": "70", "fuel_efficiency": "A", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/v8PQZbzXGNOYIUoRpUu7xw==", "noise_level_class": "B"}, {"code": "546607", "page": 7, "size": "185/65 R15", "class": "C1", "model": null, "specs": "185/65R15 88 H", "wet_grip": "B", "manufacturer": "Goodyear", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "noise_level_db": "69", "fuel_efficiency": "A", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/PkiNpyzcHVpOlOpQYNIKrw==", "noise_level_class": "B"}, {"code": "2259623", "page": 8, "size": "185/65 R15", "class": "C1", "model": "ES31", "specs": "185/65R15 88 H", "wet_grip": "A", "manufacturer": "Kumho", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "noise_level_db": "69", "fuel_efficiency": "A", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/aVYbcOK7haiqkYbYHWp4vQ==", "noise_level_class": "B"}, {"code": "0358474", "page": 8, "size": "185/65 R15", "class": "C1", "model": null, "specs": "185/65 R 15 88 H", "wet_grip": "A", "manufacturer": "Continental", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "noise_level_db": "70", "fuel_efficiency": "A", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/flyFWtFgJIsY5kdsnGzDlg==", "noise_level_class": "B"}, {"code": "0314699", "page": 8, "size": "185/65 R15", "class": "C1", "model": null, "specs": "185/65 R 15 88 H", "wet_grip": "B", "manufacturer": "Continental", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "noise_level_db": "70", "fuel_efficiency": "A", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/v8PQZbzXGNOYIUoRpUu7xw==", "noise_level_class": "B"}, {"code": "546607", "page": 9, "size": "185/65 R15", "class": "C1", "model": null, "specs": "185/65R15 88 H", "wet_grip": "B", "manufacturer": "Goodyear", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "noise_level_db": "69", "fuel_efficiency": "A", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/PkiNpyzcHVpOlOpQYNIKrw==", "noise_level_class": "B"}], "title": "Etykieta opony", "legal_note": "Zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2020/740 z dnia 25 maja 2020 r. w sprawie etykietowania opon pod kątem efektywności paliwowej i innych parametrów, zmieniające rozporządzenie (UE) 2017/1369 oraz uchylające rozporządzenie (WE) nr 1222/2009 – na stronie znajduje się lista etykiet opon wraz z dostępem do kart informacyjnych produktu (do pobrania po kliknięciu w etykietę), która przedstawia opony, jakie potencjalnie mogą być zamontowane w Twoim samochodzie. Ze względów logistycznych i produkcyjnych nie ma możliwości wyboru danej opony od konkretnego producenta opon. Więcej informacji na temat opon można uzyskać u Autoryzowanego Dealera Marki SKODA.", "wheel_description": "Stalowe obręcze kół z osłonami Calisto Aero 5,5J x 15\""}, "pricing_summary": {"items": [{"name": "Twoja konfiguracja", "price": "73 450 zł", "currency": "zł"}, {"name": "Wybrane wyposażenie opcjonalne i usługi", "price": "4000 zł", "currency": "zł"}], "title": "Ceny", "total": {"name": "Cena widocznej konfiguracji", "price": "77 450 zł", "currency": "zł"}, "financing": {"name": "Rata miesięczna *", "price": "642 zł", "currency": "zł"}}, "vehicle_summary": {"title": "Fabia", "engine": "1,0 MPI (80 KM) 59 kW 5-biegowa manualna", "version": "Essence", "visuals": [{"type": "image", "description": "Widok zewnętrzny samochodu Skoda Fabia w kolorze szarym, ustawionego pod kątem 3/4 z przodu."}, {"type": "image", "description": "Widok wnętrza samochodu, deska rozdzielcza, kierownica i ekran systemu inforozrywki."}, {"type": "image", "description": "Widok wnętrza samochodu, fotele przednie i tylne."}, {"type": "qr_code", "description": "Kod QR w prawym górnym rogu strony, prawdopodobnie prowadzący do konfiguracji online."}], "emissions_and_consumption": "Emisja CO2 w cyklu mieszanym 117 g/km / Zużycie paliwa/energii w cyklu mieszanym 5,1 l/100km"}, "document_metadata": {"data_zapisu": "23.10.2025, 11:33", "liczba_stron": 9, "id_konfiguracji": "CBW8MBBP"}, "selected_equipment": {"title": "Wybrane wyposażenie i usługi", "sections": [{"items": [{"name": "Szary Graphite Metalizowany", "price": "2400 zł"}], "category": "Kolor"}, {"items": [{"name": "Stalowe obręcze kół z osłonami Calisto Aero 5,5J x 15\"", "price": "0 zł"}], "category": "Obręcze kół"}, {"items": [{"name": "Wnętrze Studio", "price": null}], "category": "Wnętrze"}, {"items": [{"name": "Pakiet Technology", "price": "1600 zł", "components": ["Smartlink - połączenie przewodowe / bezprzewodowe dla urządzeń Apple iOS", "Skoda Surround + 4 głośniki z przodu + 2 z tyłu", "Bluetooth"]}], "category": "Pakiety rekomendowane"}]}, "standard_equipment": {"note": "* Ten element został zastąpiony opcją wybraną w ramach wyposażenia dodatkowego.", "title": "Wyposażenie standardowe", "sections": [{"items": ["Sygnalizacja ostrzegawcza niezapiętych pasów bezpieczeństwa z przodu i z tyłu", "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania z Pedestrian Monitor", "Lane Assist - asystent pasa ruchu", "Easy Light Assist - czujnik zmierzchu", "Czujnik parkowania z tyłu", "Rozpoznawanie znaków drogowych", "Driver Alert - funkcja wykrywania zmęczenia kierowcy", "Hill Hold Control - system wspomagania ruszania pod wzniesienia", "Bluetooth", "Cyfrowy zestaw wskaźników Digital Display", "Radio (ekran 8\", dwa gniazda USB-C)", "Klimatyzacja manualna", "*4 głośniki", "TPM - sygnalizacja spadku ciśnienia w oponach", "Ogranicznik prędkości"], "category": "Komfort, bezpieczeństwo i funkcjonalność"}, {"items": ["Reflektory LED Basic z przodu", "Reflektory przeciwmgłowe z przodu", "Elektrycznie sterowane szyby przednie", "Lusterka boczne w kolorze nadwozia", "Elektrycznie sterowane i podgrzewane lusterka boczne", "Chromowana ramka grilla", "Stalowe obręcze kół z osłonami Calisto Aero 5,5J x 15\""], "category": "Nadwozie"}, {"items": ["Lusterko wsteczne, przyciemnione", "Dwuramienna kierownica z tworzywa sztucznego", "Fotel kierowcy regulowany na wysokość", "Podłokietnik z przodu", "Dywaniki tekstylne", "Przestrzeń bagażowa z oświetleniem (1 lampka)"], "category": "Wnętrze"}]}, "configuration_codes": "KODY PJ3BF4/MASGEB1\\GYOKYOK, 2026, NE, 5X5X, GWUSWUS", "accessibility_information": {"title": "INFORMACJE O DOSTĘPNOŚCI", "sections": [{"title": "A. OGÓLNY OPIS USŁUG", "content": "Jesteśmy dostawcą usług e-commerce w rozumieniu Ustawy o wymogach dostępności. Oznacza to, że nasza firma może zawrzeć z Tobą umowę na odległość za pośrednictwem naszej strony internetowej lub aplikacji mobilnych bez Twojej fizycznej obecności. Niniejsze informacje dotyczące dostępności dotyczą następujących stron internetowych i aplikacji mobilnych oraz usług e-commerce, które świadczymy za ich pośrednictwem:", "services": [{"name": "a) eshop.skoda-auto.cz", "description": "Jest to usługa e-commerce, która polega na prowadzeniu sklepu internetowego, który umożliwia użytkownikom wyszukiwanie, przeglądanie, wybieranie i kupowanie towarów online (Škoda Lifestyle i Oryginalne akcesoria). Usługa obejmuje takie funkcje, jak: katalog produktów (w tym filtrowanie i wyszukiwanie), szczegółowy widok poszczególnych pozycji, dodawanie towarów do koszyka, zawieranie umowy zakupu online (mechanizm click-wrap — użytkownik zawiera umowę, aktywnie klikając przycisk, taki jak „Zamów” po zapoznaniu się z regulaminem), płatność online, komunikacja z obsługą klienta. Usługa jest dostępna za pośrednictwem interfejsu internetowego pod powyższym adresem i jest zoptymalizowana do użytku na komputerach i urządzeniach mobilnych. Nie używamy żadnego specjalistycznego sprzętu, który byłby niezbędny do uzyskania dostępu do tej usługi. Użytkownicy mogą korzystać z własnego urządzenia (np. komputera, telefonu komórkowego lub tabletu), aby uzyskać dostęp do usługi. Nasz cyfrowy interfejs jest zaprojektowany tak, aby był interoperacyjny ze standardowymi technologiami wspomagającymi."}, {"name": "b) Škoda ID", "description": "Škoda ID to cyfrowe konto użytkownika, które umożliwia poszczególnym użytkownikom dostęp do naszych usług online. Usługa zapewnia scentralizowane logowanie do cyfrowych funkcji pojazdu oraz do aplikacji internetowej i mobilnej MyŠkoda. Korzystając z Škoda ID, użytkownicy mogą zarządzać swoim osobistym profilem, łączyć swoje konto z konkretnym pojazdem, aktywować i używać wybranych funkcji pojazdu online, uzyskiwać dostęp do zdalnego sterowania pojazdem (np. klimatyzacji, blokowania), monitorować informacje o stanie pojazdu i statystyki jazdy oraz zarządzać subskrypcjami usług. Usługa jest świadczona za pośrednictwem interfejsu internetowego i aplikacji mobilnej. Nie używamy żadnego specjalistycznego sprzętu, który byłby niezbędny do uzyskania dostępu do tej usługi. Użytkownicy mogą korzystać z własnego urządzenia (np. komputera, telefonu komórkowego lub tabletu), aby uzyskać dostęp do usługi. Nasz cyfrowy interfejs jest zaprojektowany tak, aby był interoperacyjny ze standardowymi technologiami wspomagającymi."}, {"name": "c) Škoda Connect", "description": "Škoda Connect to zestaw usług online, który łączy Twój pojazd Škoda z internetem i smartfonem, oferując zwiększoną wygodę, bezpieczeństwo i informacje rozrywkowe. Oferuje funkcje takie jak aktualizacje ruchu drogowego w czasie rzeczywistym, zdalny dostęp do pojazdu (np. blokowanie/odblokowywanie, pozycja parkingowa), pomoc w nagłych wypadkach i proaktywne przypomnienia o serwisie. Usługa jest świadczona za pośrednictwem interfejsu internetowego, aplikacji mobilnej i pokładowego systemu informacyjno-rozrywkowego. Podczas korzystania z dostarczanych przez nas urządzeń upewniamy się, że ich fizyczne elementy sterujące i interfejsy oprogramowania są zgodne z wymogami dostępności i są kompatybilne z technologiami wspomagającymi."}, {"name": "d) Aplikacja mobilna MyŠkoda, Škoda Media Room", "description": "MyŠkoda to usługa cyfrowa i aplikacja mobilna, która umożliwia użytkownikom dostęp do informacji o pojeździe i zdalne sterowanie nim. Za pośrednictwem usługi użytkownicy mogą monitorować stan techniczny pojazdu, planować trasy, zarządzać ładowaniem (w przypadku samochodu elektrycznego), korzystać z usług sieciowych (np. Powerpass) i personalizować ustawienia pojazdu. Škoda Media Room to mobilna aplikacja informacyjna zaprojektowana specjalnie dla dziennikarzy, mediów i ogółu społeczeństwa zainteresowanego tym, co dzieje się wokół naszej marki. Zapewnia dostęp do aktualnych komunikatów prasowych, materiałów multimedialnych, podcastów i innych oficjalnych informacji o naszych produktach, innowacjach, wynikach i działaniach. Nie używamy żadnego specjalistycznego sprzętu, który byłby niezbędny do uzyskania dostępu do tej usługi. Użytkownicy mogą korzystać z własnego urządzenia (np. komputera, telefonu komórkowego lub tabletu), aby uzyskać dostęp do usługi. Nasz cyfrowy interfejs jest zaprojektowany tak, aby był interoperacyjny ze standardowymi technologiami wspomagającymi."}]}, {"title": "B. ZGODNOŚĆ Z WYMOGAMI DOSTĘPNOŚCI", "content": "Strony internetowe, w tym powiązane aplikacje online i usługi świadczone na urządzeniach mobilnych, w tym aplikacje mobilne, funkcje identyfikacyjne i metody identyfikacji oraz podpisy elektroniczne, są postrzegalne, funkcjonalne, zrozumiałe i stabilne. Wymagania dotyczące dostępności są zgodne ze zharmonizowaną normą EN 301 549 i normą WCAG 2.1. Aby uzyskać optymalne wyświetlanie i wydajność, należy korzystać z następujących przeglądarek internetowych:", "legal_note": "Strona internetowa i aplikacje mobilne nie są dostępne w rozumieniu prawa, w przypadku gdy nie świadczymy usług handlu elektronicznego, tj. w tych częściach strony internetowej i aplikacji mobilnych, które nie są częścią procesu zawierania umowy na odległość z konsumentem (na przykład czysto informacyjne części strony internetowej i aplikacji mobilnych). Jednak nawet w tych częściach strony internetowej i aplikacji mobilnych staramy się, aby były one dostępne dla jak najszerszego grona naszych klientów.", "requirements": [{"type": "Dla stron internetowych", "browsers": ["Chrome 116.0 i nowsze", "Safari 16.0 i nowsze", "Edge 116 i nowsze", "Firefox 116 i nowsze"]}, {"type": "Dla aplikacji mobilnych", "browsers": ["Chrome dla Androida", "Safari dla iPhone''a"]}], "os_requirements": "Aby uzyskać optymalne wyświetlanie i działanie, należy korzystać z następujących systemów operacyjnych:", "operating_systems": ["Windows: 10 i nowsze", "Mac OS: Catalina i nowsze", "iOS: 16.1 i nowsze", "Android: 9.0 i nowsze"]}, {"title": "C. USŁUGI WSPARCIA", "contact": [{"type": "Infolinia", "value": "+420 236 090 002"}, {"type": "E-mail", "value": "infoline@skoda-auto.cz"}], "content": "Nasze usługi wsparcia udzielają informacji o dostępności usług i ich zgodności z technologiami wspomagającymi. Osoby niepełnosprawne mogą również korzystać z następujących usług wsparcia:"}, {"title": "D. FORMAT AUDIO", "content": "Informacje o dostępności udostępniamy również w formacie audio. Wersja audio informacji o dostępności jest dostępna za pośrednictwem naszej infolinii."}, {"title": "E. SKUTECZNOŚĆ", "content": "Informacje te obowiązują od 28. 6. 2025 r."}], "introduction": "Niniejsze informacje o dostępności zostały zebrane przez Škoda Auto a.s. (zwaną dalej „my”) zgodnie z Dyrektywą (UE) 2019/882 Parlamentu Europejskiego i Rady z dnia 17 kwietnia 2019 r. w sprawie wymogów dostępności produktów i usług oraz Ustawą nr 424/2023 Dz.U. w sprawie wymogów dostępności niektórych produktów i usług, ze zmianami (zwaną dalej „Ustawą o wymogach dostępności”). Chcemy, aby nasze usługi cyfrowe były dostępne dla szerokiego grona klientów, w tym osób niepełnosprawnych i z innymi ograniczeniami funkcjonalnymi. Z tego powodu stale aktualizujemy nasze usługi, aby były zgodne z wymogami dostępności na mocy obowiązujących przepisów, norm, specyfikacji technicznych i najnowszych wymogów najlepszych praktyk. Niniejsze informacje o dostępności zapewniają ogólny przegląd sposobu działania naszych usług, opisują, w jaki sposób spełniamy wymogi dostępności, i zawierają dane kontaktowe dla wszystkich, którzy mają pytania dotyczące dostępności naszych usług. Informacje te są udostępniane zgodnie z § 14 Ustawy o wymogach dostępności."}, "legal_and_additional_information": {"content": [{"text": "Prezentowane są wybrane elementy wyposażenia standardowego. Domówienie pakietu lub opcji może mieć wpływ na wyposażenie standardowe – w niektórych przypadkach bezpowrotnie usuwając lub zastępując elementy.", "type": "paragraph"}, {"text": "Wszelkie prezentowane informacje, w szczególności zdjęcia, wykresy, specyfikacje, opisy, rysunki lub parametry techniczne, nie stanowią oferty w rozumieniu Kodeksu cywilnego oraz nie są wiążące i mogą ulec zmianie bez wcześniejszego powiadomienia. Prezentowane informacje nie stanowią zapewnienia w rozumieniu art. 556(1)§2 Kodeksu cywilnego. Škoda zastrzega sobie możliwość wprowadzenia zmian w prezentowanych wersjach. Przedstawione detale wyposażenia mogą różnić się od specyfikacji przewidzianej na rynek polski. Zamieszczone zdjęcia mogą przedstawiać wyposażenie opcjonalne. Wiążące ustalenie ceny, wyposażenia i specyfikacji pojazdu następuje w umowie sprzedaży, a określenie parametrów technicznych zawiera świadectwo homologacji typu pojazdu. Zastrzegamy sobie prawo do zmian i pomyłek. Wszelkie informacje prezentowane w niniejszym cenniku są aktualne na dzień publikacji materiału.", "type": "paragraph"}, {"text": "W celu uzyskania najnowszych informacji prosimy kontaktować się z Autoryzowanym Dealerem Marki Škoda Podane ceny obejmują podatek VAT (23%).", "type": "paragraph"}, {"text": "Z uwagi na ograniczenia technik drukarskich lub parametrów ekranu, na którym obraz jest wyświetlany, kolory przedstawione w niniejszym materiale mogą nieznacznie różnić się od faktycznych kolorów lakieru i materiałów. W celu uzyskania najnowszych informacji prosimy kontaktować się z Autoryzowanym Dealerem Marki Škoda.", "type": "paragraph"}, {"text": "Wszystkie produkowane obecnie samochody marki Škoda są wykonywane z materiałów spełniających pod względem możliwości odzysku i recyklingu wymagania określone w normie ISO 22628 i są zgodne z europejskimi świadectwami homologacji wydanymi wg dyrektywy 2005/64/WE. Volkswagen Group Polska sp. z o.o. podlega obowiązkowi zapewnienia wszystkim użytkownikom samochodów marki Škoda sieci odbioru pojazdów po wycofaniu ich z eksploatacji, zgodnie z wymaganiami ustawy z 20 stycznia 2005 r. o recyklingu pojazdów wycofanych z eksploatacji. Więcej informacji dotyczących ekologii znajdą Państwo na stronach: www.skoda-auto.pl/technologia/dbamy-o-srodowisko, www.skoda-auto.pl .", "type": "paragraph"}, {"text": "Od 1 września 2018 r. wszystkie nowe pojazdy wprowadzane do obrotu w Unii Europejskiej muszą być badane i homologowane zgodnie z procedurą WLTP określoną w rozporządzeniu Komisji (UE) 2017/1151. Prezentowane dane dotyczące wartości zużycia paliwa/energii, emisji CO2 lub zasięgu są danymi zgodnymi ze świadectwem homologacji typu wyznaczonymi zgodnie z procedurą WLTP. * Dane techniczne pojazdu, w tym dane wltp mogą różnić się w zależności od tygodnia produkcji. O szczegóły zapytaj u Partnerów Marki Škoda.", "type": "paragraph"}, {"text": "Montaż akcesoriów w pojeździe może mieć wpływ na poziom zużycia paliwa/energii, emisję CO2 lub zasięg oraz może nastąpić najwcześniej po pierwszej rejestracji pojazdu, wyłącznie na Państwa życzenie.", "type": "paragraph"}, {"text": "Škoda Connect. Korzystanie z usług Škoda Connect (zwanych dalej „Usługami”) wymaga zawarcia osobnej umowy przez Internet z firmą Škoda Auto, a.s. W celu skorzystania z maksymalnego czasu trwania usługi klient musi w ciągu 90 dni zarejestrować pojazd, np. za pośrednictwem portalu internetowego https://www.skoda-auto.pl/serwis/connect lub aplikacji mobilnej https://www.skoda-auto.pl/swiat-skody/myskoda-app bądź za pośrednictwem systemu infotainment w pojeździe po dostarczeniu pojazdu. Nie ma potrzeby rejestracji usługi Połączenia Alarmowego/eCall - jest ona aktywna od momentu dostawy. Dostępność Usług może się różnić w zależności od kraju, modelu pojazdu, roku modelowego i wyposażenia Pojazdu. Opisane Usługi mogą być dostępne w późniejszym czasie po przekazaniu samochodu. Usługi mogą być obsługiwane tylko przy użyciu dostępnych technologii komunikacji publicznej. Należy pamiętać, że ze względu na rozwój tych technologii, zwłaszcza sieci komórkowych, Škoda Auto nie może zagwarantować stałej dostępności we wszystkich krajach na czas trwania Usług. Ewentualne zmiany technologii mogą spowodować ich trwałą niedostępność.", "type": "paragraph"}, {"text": "W przypadku korzystania z Usług niezbędne jest również połączenie do transmisji danych pomiędzy urządzeniem Klienta (smartfon, tablet, komputer PC itp.) a serwerem danych. To połączenie do transmisji danych nie wchodzi w skład Usług. Szczegółowe informacje o usługach Škoda Connect i zapewnianych przez nie korzyściach zostały podane na stronie https://www.skoda-auto.pl/serwis/connect lub skontaktuj się z partnerem Škoda.", "type": "paragraph"}, {"text": "Zasięg dla samochodów elektrycznych lub zasięg w trybie elektrycznym dla hybryd typu Plug-In może się różnić w zależności od wersji, wyposażenia oraz zamontowanych akcesoriów, stylu jazdy, prędkości, korzystania z dodatkowych odbiorników energii, temperatury zewnętrznej, liczby pasażerów, obciążenia ładunkiem i topografii terenu. Podana maksymalna moc układu napędowego w przypadku samochodów elektrycznych lub hybryd typu Plug-In jest możliwa do uzyskania tylko w określonych warunkach. Na dostępną moc układu napędowego wpływa szereg czynników takich jak temperatura otoczenia, poziom naładowania akumulatora, jego temperatura czy stopień zużycia.", "type": "paragraph"}, {"text": "SmartLink oferuje możliwość obsługi i wyświetlania na ekranie systemu Infotainment certyfikowanych aplikacji (poprzez Android Auto lub Apple CarPlay) zainstalowanych na smartfonie podłączonym za pomocą przewodu USB (dla urządzeń z systemem Android i Apple iOS) lub bezprzewodowo (dla urządzeń z systemem Apple iOS). Działanie SmartLink uzależnione jest od wersji oprogramowania i modelu smartfona. Więcej informacji można uzyskać na stronie https://compatibilitylist.skoda-auto.com", "type": "paragraph"}, {"type": "section", "title": "Informacje o producencie i informacje o produkcie", "content": ["Škoda Auto a.s. tr. Wacława Klementa 869 293 01 Mladá Boleslav Czechy", "e-mail: biuro.vgpl1@vw-group.pl", "Instrukcja obsługi zawierająca informacje dotyczące bezpieczeństwa: https://www.skoda-auto.pl/apps/manuals/Models"]}]}}, "offer_number": null, "mapped_ai_data": {"fuel": "Benzyna (PB)", "brand": "SKODA", "model": "Fabia", "trim_level": "Essence", "engine_class": "spalinowy", "transmission": "Manualna FWD", "vehicle_type": "Osobowy", "samar_category": "Podstawowa - B MAŁE", "samar_candidates": [{"klasa": "Podstawowa - B MAŁE", "confidence": 1}, {"klasa": "Podstawowa - A MINI", "confidence": 0.1}, {"klasa": "Podstawowa - C NIŻSZA ŚREDNIA", "confidence": 0.05}], "engine_candidates": [{"klasa": "Benzyna (PB)", "confidence": 1}]}, "vehicle_vintage": "current", "financial_params": {"wibor_pct": 4.82, "margin_pct": 2, "depreciation_pct": null, "pricing_margin_pct": 15, "initial_deposit_pct": 0, "other_service_costs": 0}, "service_cost_type": "ASO", "configuration_code": "CBW8MBBP", "_extraction_metadata": {"model": "gemini-2.5-pro", "stage": "digital_twin", "output_tokens": 7530, "prompt_tokens": 3468, "thinking_tokens": 2332}}'::jsonb, 'SKODA Fabia', 0.0, '2026-03-12T18:00:13.95515+00:00', '2026-03-12T18:00:13.95515+00:00');
INSERT INTO "public"."ltr_kalkulacje" ("id", "numer_kalkulacji", "status", "stan_json", "dane_pojazdu", "cena_netto", "created_at", "updated_at") VALUES ('27916337-dfd5-470e-89e9-404770bddef9', 'KALK/2026/03/DAAA65', 'szkic_vertex', '{"brand": "Renault", "model": "ESPACE", "toggles": {"gps_required": true, "replacement_car": true, "hook_installation": false, "include_servicing": true, "express_pays_insurance": true}, "discount": {"active_final_price": 165126, "active_discount_pct": 27}, "is_metalic": true, "vehicle_id": "4c2e9a33-a793-47fe-95ff-7a9f789a16b1", "tire_params": {"tire_class": "Premium", "rim_diameter": 20, "tire_count_mode": "auto", "tire_cost_correction": 0, "tire_cost_correction_enabled": true}, "card_summary": {"fuel": "Hybryda (HEV)", "wheels": "20", "power_hp": 200, "emissions": "106 g/km, 4.7 l/100km", "base_price": "206 900 PLN brutto", "body_style": "SUV", "drive_type": "Napęd FWD", "powertrain": "1.2 E-Tech full hybrid 200 KM", "trim_level": "esprit Alpine", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 206900, "total": 226200, "options": 19300}}, "power_range": "MID (131 - 200 KM)", "total_price": "226 200 PLN brutto", "has_tow_hook": null, "paid_options": [{"name": "czarny etoile", "price": "3000 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "panoramiczny szklany dach", "price": "4500 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "pakiet winter comfort", "price": "4800 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "światła przednie full LED Matrix vision", "price": "4000 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "pakiet advanced driving assist", "price": "3000 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Automatyczna", "_price_domain": "brutto", "options_price": "19 300 PLN brutto", "vehicle_class": "Osobowy", "exterior_color": "czarny etoile 3000 PLN brutto", "engine_capacity": "1.2", "engine_category": "Hybryda (HEV)", "is_metalic_paint": true, "utility_features": [{"name": "Liczba miejsc siedzących", "value": "5"}], "service_equipment": null, "engine_designation": "E-Tech full hybrid", "standard_equipment": ["system multi-sense (3. generacji) z funkcją living lights", "zespół zegarów i wskaźników z kolorowym 12,3-calowym ekranem TFT", "openR link 12\" DAB, nawigacja, usługi Google", "j. polski", "ładowarka indukcyjna", "funkcja łączności z usługami online na 5 lat", "czarna tapicerka materiałowa łączona z Alcantarą i niebieskimi szwami", "nawiewy dla pasażerów z tyłu", "lusterko do obserwowania pasażerów 2. i 3. rzędu siedzeń", "elektrycznie i bezdotykowo otwierana klapa bagażnika", "pakiet stylistyczny wnętrza esprit Alpine", "szyby tylne sterowane elektrycznie", "system air quality (filtr PM 2.5, funkcja oczyszczania powietrza w kabinie)", "tylna kanapa przesuwana o 220 mm", "kolumna kierownicy regulowana w dwóch płaszczyznach", "klimatyzacja automatyczna dwustrefowa", "podgrzewana tylna szyba", "tapicerka materiałowa", "centralny zamek", "szyby przednie sterowane elektrycznie", "ozdobne listwy progowe", "kierownica pokryta skórą nappa, Alcantarą i przeszyciami esprit Alpine", "osłony przeciwsłoneczne z oświetleniem LED", "wysoka konsola między przednimi fotelami z podłokietnikiem", "kierunkowskazy w lusterkach bocznych", "oświetlenie wnętrza LED z włącznikiem dotykowym", "kierunkowskazy sekwencyjne", "trzecie światło stopu", "oświetlenie podłoża w lusterkach bocznych", "światła do jazdy dziennej LED", "czujnik światła i deszczu", "funkcja automatycznej zmiany świateł drogowych na mijania (AHL)", "tylne światła LED z efektem włókien 3D", "lusterko wewnętrzne elektrochromatyczne", "elektrycznie regulowane i skł