INSERT INTO "public"."ltr_kalkulacje" ("id", "numer_kalkulacji", "status", "stan_json", "dane_pojazdu", "cena_netto", "created_at", "updated_at") VALUES ('657c5994-ad1f-4772-acd4-dcab148b868c', 'KALK/2026/03/7BD5C5', 'szkic_vertex', '{"brand": "SKODA", "model": "Octavia Combi", "toggles": {"gps_required": true, "replacement_car": true, "hook_installation": false, "include_servicing": true, "express_pays_insurance": true}, "discount": {"active_final_price": 100192.5, "active_discount_pct": 27}, "is_metalic": true, "vehicle_id": "dd091416-8900-45cd-bf07-a945e4d1a596", "tire_params": {"tire_class": "Medium", "rim_diameter": 16, "tire_count_mode": "auto", "tire_cost_correction": 0, "tire_cost_correction_enabled": true}, "card_summary": {"fuel": "Benzyna mHEV", "wheels": "16", "power_hp": 115, "emissions": "115 g/km, 5,0 l/100km (WLTP)", "base_price": "130 200 PLN brutto", "body_style": "Kombi", "drive_type": "Napęd FWD", "powertrain": "1.5 TSI m-HEV 115 KM (85 kW)", "trim_level": "Edition 130 Essence", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 130200, "total": 137250, "options": 7050}}, "power_range": "LOW (do 130 KM)", "total_price": "137 250 PLN brutto", "has_tow_hook": null, "paid_options": [{"name": "Szary Graphite Metalizowany", "price": "2650 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Na Bezdroża", "price": "900 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Simply Clever", "price": "600 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Zapasowe koło stalowe dojazdowe 16\", podnośnik, klucz", "price": "700 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Rozszerzony System Bezpieczeństwa (PreCrash)", "price": "900 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Kessy Go z Alarmem i funkcją Safe", "price": "1300 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Automatyczna", "_price_domain": "brutto", "options_price": "7050 PLN brutto", "vehicle_class": "Osobowy", "exterior_color": "Szary Graphite Metalizowany", "engine_capacity": "1.5", "engine_category": "Benzyna mHEV (PB-mHEV)", "is_metalic_paint": true, "utility_features": [], "service_equipment": null, "engine_designation": "TSI m-HEV", "standard_equipment": ["Reflektory LED Basic", "Tylne światła LED TOP z dynamicznymi kierunkowskazami", "Czujniki parkowania - przód i tył", "Infotainment 10\"", "Kamera cofania", "SmartLink", "Attention and Drowsiness Assist - funkcja wykrywania zmęczenia kierowcy", "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania", "Light and Rain Assist - czujnik zmierzchu i deszczu", "Lane Assist - asystent pasa ruchu", "Automatycznie ściemniające się lusterko wsteczne", "8 głośników", "Rozpoznawanie znaków drogowych", "Tempomat", "TPM - system kontroli ciśnienia w oponach", "Climatronic - automatyczna klimatyzacja dwustrefowa", "Elektrycznie składane lusterka boczne", "Side Assist - funkcja monitorowania martwego pola", "Skórzana 2-ramienna kierownica wielofunkcyjna z manetkami", "Podłokietnik z przodu", "Uchwyty Isofix"], "financial_reasoning": "Na podstawie sekcji ''pricing'' zidentyfikowano następujące kwoty: ''Twoja konfiguracja'' (cena bazowa) wynosi 130 200 zł, ''Wybrane wyposażenie opcjonalne i usługi'' (cena opcji) wynosi 7050 zł, a ''Cena widocznej konfiguracji'' (cena całkowita) wynosi 137 250 zł. Sprawdzenie matematyczne: 130 200 zł + 7050 zł = 137 250 zł, co potwierdza poprawność tych wartości. W sekcji ''legal_disclaimers'' znajduje się informacja: ''Podane ceny obejmują podatek VAT (23%)'', co jednoznacznie wskazuje, że wszystkie kwoty są kwotami brutto.", "suggested_discount_pct": 27, "is_current_year_vehicle": true, "suggested_discount_source": "Dopasowano do modelu SKODA Octavia Combi (elastyczne dopasowanie ''Combi'' do ''Kombi'') oraz kodu konfiguracji ''PV5***'' z rabatem 27.0%.", "suggested_discount_confidence": 98}, "digital_twin": {"pricing": {"title": "Ceny", "currency": "zł", "financing": {"name": "Rata miesięczna *", "value": "1115 zł"}, "total_price": {"name": "Cena widocznej konfiguracji", "value": "137 250 zł"}, "price_components": [{"name": "Twoja konfiguracja", "value": "130 200 zł"}, {"name": "Wybrane wyposażenie opcjonalne i usługi", "value": "7050 zł"}]}, "metadata": {"document_type": "Oferta na samochód"}, "vehicle_summary": {"name": "Octavia Combi", "engine": "1,5 TSI m-HEV (115 KM) 85 kW 7-biegowa automatyczna", "version": "Edition 130 Essence", "visuals": [{"type": "main_vehicle_image", "description": "Widok na szary samochód Skoda Octavia Combi z perspektywy przedniego lewego boku. Na oponie widoczny napis Octavia Combi."}, {"type": "interior_image", "description": "Widok na deskę rozdzielczą i przednie fotele od strony pasażera."}, {"type": "interior_image", "description": "Widok na tylne siedzenia samochodu."}], "environmental_data": {"co2_emission_mixed": "115 g/km", "fuel_consumption_mixed": "5,0 l/100km"}, "technical_specifications": {"power_hp": "115 KM", "power_kw": "85 kW", "engine_type": "1,5 TSI m-HEV", "transmission": "7-biegowa automatyczna"}}, "document_metadata": {"type": "Konfiguracja pojazdu", "warning": "Your configuration ID CBQDKGWL is no longer available and has expired.", "save_date": "20.08.2025, 14:33", "page_count": 7}, "legal_disclaimers": [{"page": 3, "content": "Prezentowane są wybrane elementy wyposażenia standardowego. Domówienie pakietu lub opcji może mieć wpływ na wyposażenie standardowe – w niektórych przypadkach bezpowrotnie usuwając lub zastępując elementy. Wszelkie prezentowane informacje, w szczególności zdjęcia, wykresy, specyfikacje, opisy, rysunki lub parametry techniczne, nie stanowią oferty w rozumieniu Kodeksu cywilnego oraz nie są wiążące i mogą ulec zmianie bez wcześniejszego powiadomienia. Prezentowane informacje nie stanowią zapewnienia w rozumieniu art. 556(1)§2 Kodeksu cywilnego. Škoda zastrzega sobie możliwość wprowadzenia zmian w prezentowanych wersjach. Przedstawione detale wyposażenia mogą różnić się od specyfikacji przewidzianej na rynek polski. Zamieszczone zdjęcia mogą przedstawiać wyposażenie opcjonalne. Wiążące ustalenie ceny, wyposażenia i specyfikacji pojazdu następuje w umowie sprzedaży, a określenie parametrów technicznych zawiera świadectwo homologacji typu pojazdu. Zastrzegamy sobie prawo do zmian i pomyłek. Wszelkie informacje prezentowane w niniejszym cenniku są aktualne na dzień publikacji materiału. W celu uzyskania najnowszych informacji prosimy kontaktować się z Autoryzowanym Dealerem Marki Škoda Podane ceny obejmują podatek VAT (23%). Z uwagi na ograniczenia technik drukarskich lub parametrów ekranu, na którym obraz jest wyświetlany, kolory przedstawione w niniejszym materiale mogą nieznacznie różnić się od faktycznych kolorów lakieru i materiałów. W celu uzyskania najnowszych informacji prosimy kontaktować się z Autoryzowanym Dealerem Marki Škoda. Wszystkie produkowane obecnie samochody marki Škoda są wykonywane z materiałów spełniających pod względem możliwości odzysku i recyklingu wymagania określone w normie ISO 22628 i są zgodne z europejskimi świadectwami homologacji wydanymi wg dyrektywy 2005/64/WE. Volkswagen Group Polska sp. z o.o. podlega obowiązkowi zapewnienia wszystkim użytkownikom samochodów marki Škoda sieci odbioru pojazdów po wycofaniu ich z eksploatacji, zgodnie z wymaganiami ustawy z 20 stycznia 2005 r. o recyklingu pojazdów wycofanych z eksploatacji. Więcej informacji dotyczących ekologii znajdą Państwo na stronach: www.skoda-auto.pl/technologia/dbamy-o-srodowisko, www.skoda-auto.pl . Od 1 września 2018 r. wszystkie nowe pojazdy wprowadzane do obrotu w Unii Europejskiej muszą być badane i homologowane zgodnie z procedurą WLTP określoną w rozporządzeniu Komisji (UE) 2017/1151. Prezentowane dane"}, {"page": 4, "content": "dotyczące wartości zużycia paliwa/energii, emisji CO2 lub zasięgu są danymi zgodnymi ze świadectwem homologacji typu wyznaczonymi zgodnie z procedurą WLTP. * Dane techniczne pojazdu, w tym dane wltp mogą różnić się w zależności od tygodnia produkcji. O szczegóły zapytaj u Partnerów Marki Škoda. Montaż akcesoriów w pojeździe może mieć wpływ na poziom zużycia paliwa/energii, emisję CO2 lub zasięg oraz może nastąpić najwcześniej po pierwszej rejestracji pojazdu, wyłącznie na Państwa życzenie. Škoda Connect Korzystanie z usług Škoda Connect (zwanych dalej „Usługami”) wymaga zawarcia osobnej umowy przez Internet z firmą Škoda Auto, a.s. W celu skorzystania z maksymalnego czasu trwania usługi klient musi w ciągu 90 dni zarejestrować pojazd, np. za pośrednictwem portalu internetowego https://www.skoda-auto.pl/serwis/connect lub aplikacji mobilnej https://www.skoda-auto.pl/swiat-skody/myskoda-app bądź za pośrednictwem systemu infotainment w pojeździe po dostarczeniu pojazdu. Nie ma potrzeby rejestracji usługi Połączenia Alarmowego/eCall - jest ona aktywna od momentu dostawy. Dostępność Usług może się różnić w zależności od kraju, modelu pojazdu, roku modelowego i wyposażenia Pojazdu. Opisane Usługi mogą być dostępne w późniejszym czasie po przekazaniu samochodu. Usługi mogą być obsługiwane tylko przy użyciu dostępnych technologii komunikacji publicznej. Należy pamiętać, że ze względu na rozwój tych technologii, zwłaszcza sieci komórkowych, Škoda Auto nie może zagwarantować stałej dostępności we wszystkich krajach na czas trwania Usług. Ewentualne zmiany technologii mogą spowodować ich trwałą niedostępność. W przypadku korzystania z Usług niezbędne jest również połączenie do transmisji danych pomiędzy urządzeniem Klienta (smartfon, tablet, komputer PC itp.) a serwerem danych. To połączenie do transmisji danych nie wchodzi w skład Usług. Szczegółowe informacje o usługach Škoda Connect i zapewnianych przez nie korzyściach zostały podane na stronie https://www.skoda-auto.pl/serwis/connect lub skontaktuj się z partnerem Škoda. Zasięg dla samochodów elektrycznych lub zasięg w trybie elektrycznym dla hybryd typu Plug-In może się różnić w zależności od wersji, wyposażenia oraz zamontowanych akcesoriów, stylu jazdy, prędkości, korzystania z dodatkowych odbiorników energii, temperatury zewnętrznej, liczby pasażerów, obciążenia ładunkiem i topografii terenu. Podana maksymalna moc układu napędowego w przypadku samochodów elektrycznych lub hybryd typu Plug-In jest możliwa do uzyskania tylko w określonych warunkach. Na dostępną moc układu napędowego wpływa szereg czynników takich jak temperatura otoczenia, poziom naładowania akumulatora, jego temperatura czy stopień zużycia. SmartLink oferuje możliwość obsługi i wyświetlania na ekranie systemu Infotainment certyfikowanych aplikacji (poprzez Android Auto lub Apple CarPlay) zainstalowanych na smartfonie podłączonym za pomocą przewodu USB (dla urządzeń z systemem Android i Apple iOS) lub bezprzewodowo (dla urządzeń z systemem Apple iOS). Działanie SmartLink uzależnione jest od wersji oprogramowania i modelu smartfona. Więcej informacji można uzyskać na stronie https://compatibilitylist.skoda-auto.com"}], "selected_equipment": {"codes": "PV5BAD/MASGEB1\\GWPBWPB\\GYOKYOK, 2026, YD, 5X5X, MESI7W7, GPDFPDF, GPFAPFA, GPSBPSB, GPJAPJA", "items": [{"name": "Szary Graphite Metalizowany", "price": "2650 zł", "category": "Kolor"}, {"name": "Obręcze kół ze stopów lekkich Matar Aero 7J x 16\"", "price": "0 zł", "category": "Obręcze kół"}, {"name": "Studio", "price": null, "category": "Wnętrze"}, {"items": [{"name": "Pakiet Na Bezdroża", "price": "900 zł", "components": ["Amortyzacja tył, podniesione podwozie o 15 mm", "Amortyzacja przód", "Dodatkowa osłona podwozia", "Osłona podwozia"]}, {"name": "Pakiet Simply Clever", "price": "600 zł", "components": ["Zestaw siatek oraz elementy mocujące (cargo) w komorze bagażnika", "Schowki w bagażniku po obu stronach"]}, {"name": "Zapasowe koło stalowe dojazdowe 16\", podnośnik, klucz", "price": "700 zł"}], "category": "Funkcjonalność"}, {"items": [{"name": "Rozszerzony System Bezpieczeństwa (PreCrash)", "price": "900 zł"}, {"name": "Kessy Go z Alarmem i funkcją Safe", "price": "1300 zł"}], "category": "Bezpieczeństwo"}], "title": "Wybrane wyposażenie i usługi"}, "standard_equipment": {"title": "Wyposażenie standardowe", "sections": [{"title": "Komfort, bezpieczeństwo i funkcjonalność", "features": ["Reflektory LED Basic", "Tylne światła LED TOP z dynamicznymi kierunkowskazami", "Czujniki parkowania - przód i tył", "Infotainment 10\"", "Kamera cofania", "SmartLink - połączenie przewodowe/bezprzewodowe dla urządzeń Apple iOS", "Attention and Drowsiness Assist - funkcja wykrywania zmęczenia kierowcy", "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania oraz Collision Avoidance Assist", "Light and Rain Assist - czujnik zmierzchu i deszczu", "Lane Assist - asystent pasa ruchu", "Sygnalizacja ostrzegawcza niezapiętych pasów bezpieczeństwa", "Automatycznie ściemniające się lusterko wsteczne z czujnikiem wilgotności", "8 głośników", "Turn Assist - asystent skrętu", "Rozpoznawanie znaków drogowych", "HHC - Hill-hold control", "Tempomat", "TPM - system kontroli ciśnienia w oponach", "DAB+ - cyfrowy odbiór stacji radiowych", "Climatronic - automatyczna klimatyzacja dwustrefowa z regulacją elektroniczną", "Elektrycznie składane lusterka boczne, automatycznie przyciemniające się lusterko po stronie kierowcy", "Boczne poduszki powietrzne z centralną poduszką powietrzną", "Czołowe poduszki bezpieczeństwa kierowcy i pasażera z przodu, dezaktywacja poduszki bezpieczeństwa pasażera z przodu, poduszka kolanowa kierowcy", "Inteligentny ogranicznik prędkości", "Side Assist - funkcja monitorowania martwego pola z Rear Traffic Alert i Exit Warning", "Zwijana roleta nad przestrzenią bagażową (Combi)", "Crossroad Assist"]}, {"title": "Nadwozie", "features": ["4 USB-C oraz gniazdo USB w lusterku wstecznym", "Lusterka boczne i klamki w kolorze nadwozia", "Elektrycznie sterowane szyby przednie i tylne", "Obręcze kół ze stopów lekkich Matar Aero 7J x 16\""]}, {"title": "Wnętrze", "features": ["Skórzana 2-ramienna kierownica wielofunkcyjna z manetkami", "Fotel kierowcy i pasażera regulowany na wysokość wraz z regulacją pod lędźwie", "Podłokietnik z przodu", "Uchwyty Isofix na zewnętrznych miejscach z tyłu oraz na fotelu pasażera z przodu", "Oświetlenie części bagażowej - 2 lampki", "Gniazdo 12V w bagażniku"]}]}, "producer_information": {"email": "biuro.vgpl1@vw-group.pl", "title": "Informacje o producencie i informacje o produkcie", "address": "tr. Wacława Klementa 869 293 01 Mladá Boleslav Czechy", "company": "Škoda Auto a.s.", "manuals_url": "https://www.skoda-auto.pl/apps/manuals/Models"}, "tire_label_information": {"tires": [{"size": "205/60 R16", "brand": "Hankook", "class": "C1", "noise_db": "68 dB", "wet_grip": "A", "model_code": "1028694", "noise_class": "A", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "fuel_efficiency": "A", "load_speed_index": "92 V", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/nLrnXtqSh+biGPP2vTT05Q=="}, {"size": "205/60 R16", "brand": "Kumho", "class": "C1", "model": "PS71", "noise_db": "71 dB", "wet_grip": "B", "model_code": "2267663", "noise_class": "B", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "fuel_efficiency": "A", "load_speed_index": "92 V", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/2ufO20yE0gb/vD/Dg5XFOg=="}, {"size": "205/60 R16", "brand": "Goodyear", "class": "C1", "noise_db": "71 dB", "wet_grip": "B", "model_code": "546288", "noise_class": "B", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "fuel_efficiency": "A", "load_speed_index": "92 V", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/o5qhRnkrfHo+LfkrCEqLvg=="}], "title": "Etykieta opony", "subtitle": "Obręcze kół ze stopów lekkich Matar Aero 7J x 16\"", "disclaimer": "Zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2020/740 z dnia 25 maja 2020 r. w sprawie etykietowania opon pod kątem efektywności paliwowej i innych parametrów, zmieniające rozporządzenie (UE) 2017/1369 oraz uchylające rozporządzenie (WE) nr 1222/2009 – na stronie znajduje się lista etykiet opon wraz z dostępem do kart informacyjnych produktu (do pobrania po kliknięciu w etykietę), która przedstawia opony, jakie potencjalnie mogą być zamontowane w Twoim samochodzie. Ze względów logistycznych i produkcyjnych nie ma możliwości wyboru danej opony od konkretnego producenta opon. Więcej informacji na temat opon można uzyskać u Autoryzowanego Dealera Marki SKODA."}, "accessibility_information": {"title": "INFORMACJE O DOSTĘPNOŚCI", "sections": [{"title": "A. OGÓLNY OPIS USŁUG", "content": "Jesteśmy dostawcą usług e-commerce w rozumieniu Ustawy o wymogach dostępności. Oznacza to, że nasza firma może zawrzeć z Tobą umowę na odległość za pośrednictwem naszej strony internetowej lub aplikacji mobilnych bez Twojej fizycznej obecności. Niniejsze informacje dotyczące dostępności dotyczą następujących stron internetowych i aplikacji mobilnych oraz usług e-commerce, które świadczymy za ich pośrednictwem:", "services": [{"name": "a) eshop.skoda-auto.cz", "description": "Jest to usługa e-commerce, która polega na prowadzeniu sklepu internetowego, który umożliwia użytkownikom wyszukiwanie, przeglądanie, wybieranie i kupowanie towarów online (Škoda Lifestyle i Oryginalne akcesoria). Usługa obejmuje takie funkcje, jak: katalog produktów (w tym filtrowanie i wyszukiwanie), szczegółowy widok poszczególnych pozycji, dodawanie towarów do koszyka, zawieranie umowy zakupu online (mechanizm click-wrap — użytkownik zawiera umowę, aktywnie klikając przycisk, taki jak „Zamów” po zapoznaniu się z regulaminem), płatność online, komunikacja z obsługą klienta. Usługa jest dostępna za pośrednictwem interfejsu internetowego pod powyższym adresem i jest zoptymalizowana do użytku na komputerach i urządzeniach mobilnych. Nie używamy żadnego specjalistycznego sprzętu, który byłby niezbędny do uzyskania dostępu do tej usługi. Użytkownicy mogą korzystać z własnego urządzenia (np. komputera, telefonu komórkowego lub tabletu), aby uzyskać dostęp do usługi. Nasz cyfrowy interfejs jest zaprojektowany tak, aby był interoperacyjny ze standardowymi technologiami wspomagającymi."}, {"name": "b) Škoda ID", "description": "Škoda ID to cyfrowe konto użytkownika, które umożliwia poszczególnym użytkownikom dostęp do naszych usług online. Usługa zapewnia scentralizowane logowanie do cyfrowych funkcji pojazdu oraz do aplikacji internetowej i mobilnej MyŠkoda. Korzystając z Škoda ID, użytkownicy mogą zarządzać swoim osobistym profilem, łączyć swoje konto z konkretnym pojazdem, aktywować i używać wybranych funkcji pojazdu online, uzyskiwać dostęp do zdalnego sterowania pojazdem (np. klimatyzacji, blokowania), monitorować informacje o stanie pojazdu i statystyki jazdy oraz zarządzać subskrypcjami usług. Usługa jest świadczona za pośrednictwem interfejsu internetowego i aplikacji mobilnej. Nie używamy żadnego specjalistycznego sprzętu, który byłby niezbędny do uzyskania dostępu do tej usługi. Użytkownicy mogą korzystać z własnego urządzenia (np. komputera, telefonu komórkowego lub tabletu), aby uzyskać dostęp do usługi. Nasz cyfrowy interfejs jest zaprojektowany tak, aby był interoperacyjny ze standardowymi technologiami wspomagającymi."}, {"name": "c) Škoda Connect", "description": "Škoda Connect to zestaw usług online, który łączy Twój pojazd Škoda z internetem i smartfonem, oferując zwiększoną wygodę, bezpieczeństwo i informacje rozrywkowe. Oferuje funkcje takie jak aktualizacje ruchu drogowego w czasie rzeczywistym, zdalny dostęp do pojazdu (np. blokowanie/odblokowywanie, pozycja parkingowa), pomoc w nagłych wypadkach i proaktywne przypomnienia o serwisie. Usługa jest świadczona za pośrednictwem interfejsu internetowego, aplikacji mobilnej i pokładowego systemu informacyjno-rozrywkowego. Podczas korzystania z dostarczanych przez nas urządzeń upewniamy się, że ich fizyczne elementy sterujące i interfejsy oprogramowania są zgodne z wymogami dostępności i są kompatybilne z technologiami wspomagającymi."}, {"name": "d) Aplikacja mobilna MyŠkoda, Škoda Media Room", "description": "MyŠkoda to usługa cyfrowa i aplikacja mobilna, która umożliwia użytkownikom dostęp do informacji o pojeździe i zdalne sterowanie nim. Za pośrednictwem usługi użytkownicy mogą monitorować stan techniczny pojazdu, planować trasy, zarządzać ładowaniem (w przypadku samochodu elektrycznego), korzystać z usług sieciowych (np. Powerpass) i personalizować ustawienia pojazdu. Škoda Media Room to mobilna aplikacja informacyjna zaprojektowana specjalnie dla dziennikarzy, mediów i ogółu społeczeństwa zainteresowanego tym, co dzieje się wokół naszej marki. Zapewnia dostęp do aktualnych komunikatów prasowych, materiałów multimedialnych, podcastów i innych oficjalnych informacji o naszych produktach, innowacjach, wynikach i działaniach. Nie używamy żadnego specjalistycznego sprzętu, który byłby niezbędny do uzyskania dostępu do tej usługi. Użytkownicy mogą korzystać z własnego urządzenia (np. komputera, telefonu komórkowego lub tabletu), aby uzyskać dostęp do usługi. Nasz cyfrowy interfejs jest zaprojektowany tak, aby był interoperacyjny ze standardowymi technologiami wspomagającymi."}]}, {"title": "B. ZGODNOŚĆ Z WYMOGAMI DOSTĘPNOŚCI", "content": "Strony internetowe, w tym powiązane aplikacje online i usługi świadczone na urządzeniach mobilnych, w tym aplikacje mobilne, funkcje identyfikacyjne i metody identyfikacji oraz podpisy elektroniczne, są postrzegalne, funkcjonalne, zrozumiałe i stabilne. Wymagania dotyczące dostępności są zgodne ze zharmonizowaną normą EN 301 549 i normą WCAG 2.1.", "disclaimer": "Strona internetowa i aplikacje mobilne nie są dostępne w rozumieniu prawa, w przypadku gdy nie świadczymy usług handlu elektronicznego, tj. w tych częściach strony internetowej i aplikacji mobilnych, które nie są częścią procesu zawierania umowy na odległość z konsumentem (na przykład czysto informacyjne części strony internetowej i aplikacji mobilnych). Jednak nawet w tych częściach strony internetowej i aplikacji mobilnych staramy się, aby były one dostępne dla jak najszerszego grona naszych klientów.", "requirements": {"browsers": ["Chrome 116.0 i nowsze", "Safari 16.0 i nowsze", "Edge 116 i nowsze", "Firefox 116 i nowsze"], "operating_systems": ["Windows: 10 i nowsze", "Mac OS: Catalina i nowsze", "iOS: 16.1 i nowsze", "Android: 9.0 i nowsze"], "mobile_apps_browsers": ["Chrome dla Androida", "Safari dla iPhone''a"]}}, {"title": "C. USŁUGI WSPARCIA", "contact": [{"type": "Infolinia", "value": "+420 236 090 002"}, {"type": "E-mail", "value": "infoline@skoda-auto.cz"}], "content": "Nasze usługi wsparcia udzielają informacji o dostępności usług i ich zgodności z technologiami wspomagającymi. Osoby niepełnosprawne mogą również korzystać z następujących usług wsparcia:"}, {"title": "D. FORMAT AUDIO", "content": "Informacje o dostępności udostępniamy również w formacie audio. Wersja audio informacji o dostępności jest dostępna za pośrednictwem naszej infolinii."}, {"title": "E. SKUTECZNOŚĆ", "content": "Informacje te obowiązują od 28. 6. 2025 r."}], "introduction": "Niniejsze informacje o dostępności zostały zebrane przez Škoda Auto a.s. (zwaną dalej „my”) zgodnie z Dyrektywą (UE) 2019/882 Parlamentu Europejskiego i Rady z dnia 17 kwietnia 2019 r. w sprawie wymogów dostępności produktów i usług oraz Ustawą nr 424/2023 Dz.U. w sprawie wymogów dostępności niektórych produktów i usług, ze zmianami (zwaną dalej „Ustawą o wymogach dostępności”). Chcemy, aby nasze usługi cyfrowe były dostępne dla szerokiego grona klientów, w tym osób niepełnosprawnych i z innymi ograniczeniami funkcjonalnymi. Z tego powodu stale aktualizujemy nasze usługi, aby były zgodne z wymogami dostępności na mocy obowiązujących przepisów, norm, specyfikacji technicznych i najnowszych wymogów najlepszych praktyk. Niniejsze informacje o dostępności zapewniają ogólny przegląd sposobu działania naszych usług, opisują, w jaki sposób spełniamy wymogi dostępności, i zawierają dane kontaktowe dla wszystkich, którzy mają pytania dotyczące dostępności naszych usług. Informacje te są udostępniane zgodnie z § 14 Ustawy o wymogach dostępności."}}, "offer_number": null, "mapped_ai_data": {"fuel": "Benzyna mHEV (PB-mHEV)", "brand": "SKODA", "model": "Octavia Combi", "trim_level": "Edition 130 Essence", "engine_class": "mhev", "transmission": "7-biegowa automatyczna", "vehicle_type": "Osobowy", "samar_category": "Podstawowa - C NIŻSZA ŚREDNIA", "samar_candidates": [{"klasa": "Podstawowa - C NIŻSZA ŚREDNIA", "confidence": 1}, {"klasa": "Podstawowa - D ŚREDNIA", "confidence": 0.1}], "engine_candidates": [{"klasa": "Benzyna mHEV (PB-mHEV)", "confidence": 1}, {"klasa": "Benzyna (PB)", "confidence": 0.1}, {"klasa": "Hybryda (HEV)", "confidence": 0.05}]}, "vehicle_vintage": "current", "financial_params": {"wibor_pct": 4.82, "margin_pct": 2, "depreciation_pct": null, "pricing_margin_pct": 12, "initial_deposit_pct": 0, "other_service_costs": 0}, "service_cost_type": "nonASO", "configuration_code": "CBQDKGWL", "_extraction_metadata": {"model": "gemini-2.5-pro", "stage": "digital_twin", "output_tokens": 6791, "prompt_tokens": 2952, "thinking_tokens": 2547}}'::jsonb, 'SKODA Octavia Combi', 0.0, '2026-03-12T09:37:29.318008+00:00', '2026-03-12T09:37:29.318008+00:00');
