INSERT INTO "public"."ltr_kalkulacje" ("id", "numer_kalkulacji", "status", "stan_json", "dane_pojazdu", "cena_netto", "created_at", "updated_at") VALUES ('bfe3c05f-675c-40a0-a279-046ed8024620', 'KALK/2026/03/F52A24', 'szkic_vertex', '{"brand": "SKODA", "model": "Superb Combi", "toggles": {"gps_required": true, "replacement_car": true, "hook_installation": true, "include_servicing": true, "express_pays_insurance": true}, "discount": {"active_final_price": 198834.00072, "active_discount_pct": 24}, "is_metalic": true, "vehicle_id": "f951d2fb-6dac-43db-9e07-f7ec7907c112", "tire_params": {"tire_class": "Premium", "rim_diameter": 19, "tire_count_mode": "auto", "tire_cost_correction": 0, "tire_cost_correction_enabled": true}, "card_summary": {"fuel": "Benzyna", "wheels": "19", "power_hp": 204, "emissions": "Emisja CO2: 157 g/km, Zużycie paliwa: 6,9 l/100km (cykl mieszany)", "base_price": "215900 PLN brutto", "body_style": "Kombi", "drive_type": "Napęd FWD", "powertrain": "2,0 TSI 204 KM", "trim_level": "Sportline", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 215900, "total": 261330, "options": 45430}}, "power_range": "HIGH (201 KM i więcej)", "total_price": "261330 PLN brutto", "has_tow_hook": true, "paid_options": [{"name": "Czerwień Carmine Metalizowany", "price": "3600 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Obręcze kół ze stopów lekkich 8J x 19\" Torcular, czarne", "price": "3100 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Infotainment Plus", "price": "2500 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Niezależny system ogrzewania ze zdalnym sterowaniem", "price": "6300 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Sound System Canton (14 głośników)", "price": "3400 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Dach panoramiczny", "price": "6500 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Climate", "price": "2700 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Design Selection Suite Sportline", "price": "4200 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Assisted Drive Basic", "price": "3000 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Family and Business", "price": "2400 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Hak holowniczy (składany)", "price": "3800 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Siatka oddzielająca przestrzeń bagażową od pasażerskiej", "price": "800 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Wielofunkcyjna podłoga bagażnika z organizerem", "price": "1400 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Stalowe koło zapasowe", "price": "800 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Folia ochronna zderzaka tylnego", "price": "200 PLN brutto", "category": "Serwisowa/Akcesoria", "price_type": "brutto"}, {"name": "Plastikowa wykładzina podłogi bagażnika", "price": "730 PLN brutto", "category": "Serwisowa/Akcesoria", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Automatyczna", "_price_domain": "brutto", "options_price": "45430 PLN brutto", "vehicle_class": "Osobowy", "exterior_color": "Czerwień Carmine Metalizowany", "engine_capacity": "2.0", "engine_category": "Benzyna (PB)", "is_metalic_paint": true, "utility_features": [], "service_equipment": null, "engine_designation": "TSI", "standard_equipment": ["Kamera cofania", "Kessy Full - bezkluczykowy system obsługi samochodu (z funkcją Safe)", "13\" Wyświetlacz", "Climatronic - automatyczna klimatyzacja trójstrefowa", "Reflektory Full LED Matrix", "Side Assist - funkcja monitorowania martwego pola z Rear Traffic Alert oraz Exit Warning", "Asystent skrętu", "Funkcja rozpoznawania znaków drogowych", "Virtual Cockpit - cyfrowy zestaw wskaźników", "Bezprzewodowa szybka ładowarka indukcyjna", "Funkcja SmartLink - łączność bezprzewodowa", "Nawigacja", "Acoustic package wraz z Sunset (dźwiękochłonne szyby boczne przednie i tylne)", "Oświetlenie Ambiente", "Elektryczna roleta przestrzeni bagażowej", "Alarm z funkcją monitorowania wnętrza", "Czujniki parkowania z przodu i z tyłu", "Proaktywna ochrona pasażerów", "Driving Mode Select - wybór profilu jazdy", "Relingi dachowe, czarny połysk", "Bezdotykowo otwierana, elektrycznie sterowana pokrywa bagażnika z funkcją Easy Close", "Tylne światła LED z dynamicznymi kierunkowskazami", "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania", "Elektrycznie sterowane i składane, podgrzewane lusterka boczne z funkcją pamięci", "Sportowy zderzak", "Elektrycznie regulowane fotele przednie z funkcją pamięci oraz funkcją Smart Comfort Entry", "Sportowe fotele z przodu"], "financial_reasoning": "Na stronie 1 dokumentu znajduje się podsumowanie cenowe. ''Twoja konfiguracja'' (cena bazowa) wynosi 215 900 zł. ''Wybrane wyposażenie opcjonalne i usługi'' (cena opcji) wynosi 45 430 zł. ''Cena widocznej konfiguracji'' (cena całkowita) wynosi 261 330 zł. Sprawdzenie matematyczne: 215 900 zł + 45 430 zł = 261 330 zł. Suma się zgadza. Dodatkowo, zsumowałem wszystkie pozycje z listy wyposażenia dodatkowego na stronie 2, a ich suma również wynosi 45 430 zł. W nocie prawnej na stronie 4 znajduje się informacja: ''Prezentowane ceny są wyłącznie cenami rekomendowanymi i obejmują podatek VAT (23%)'', co jednoznacznie wskazuje, że wszystkie podane kwoty są cenami brutto.", "suggested_discount_pct": 24, "is_current_year_vehicle": true, "suggested_discount_source": "Pojazd to SKODA Superb Combi, co dokładnie odpowiada pozycji ''SUPERB KOMBI NG'' w bazie rabatów. Kod konfiguracji pojazdu zawiera również prefiks ''NZ5'', zgodny z kodem rabatu ''NZ5***''.", "suggested_discount_confidence": 95}, "digital_twin": {"pages": [{"content": [{"type": "header", "details": "ID konfiguracji: CPPXSHCN\nZapisano: 12.03.2026, 19:26", "qr_code": "Obecny", "brand_logo": "SKODA"}, {"type": "vehicle_title", "title": "Superb Combi", "engine": "2,0 TSI (204 KM) 150 kW 7-biegowa automatyczna", "subtitle": "Sportline", "emissions_info": "Emisja CO2 w cyklu mieszanym 157 g/km / Zużycie paliwa/energii w cyklu mieszanym 6,9 l/100km"}, {"type": "visual_elements", "images": [{"description": "Główne zdjęcie przedstawiające czerwony samochód Skoda Superb Combi Sportline, widok z przodu i z boku."}, {"description": "Zdjęcie wnętrza pojazdu, pokazujące deskę rozdzielczą, kierownicę i ekran systemu multimedialnego."}, {"description": "Zdjęcie wnętrza pojazdu, pokazujące tylne siedzenia."}]}, {"type": "pricing_summary", "table": [{"item": "Twoja konfiguracja", "price": "215 900 zł"}, {"item": "Wybrane wyposażenie opcjonalne i usługi", "price": "45 430 zł"}, {"item": "Cena widocznej konfiguracji", "price": "261 330 zł"}, {"item": "Rata miesięczna *", "price": "2578 zł"}], "title": "Ceny"}, {"text": "Strona 1 / 6", "type": "footer"}], "page_number": 1}, {"content": [{"type": "header", "details": "ID konfiguracji: CPPXSHCN\nZapisano: 12.03.2026, 19:26", "qr_code": "Obecny", "brand_logo": "SKODA"}, {"type": "selected_options", "title": "Wybrane wyposażenie i usługi", "sections": [{"items": [{"name": "Czerwień Carmine Metalizowany", "price": "3600 zł"}], "category": "Kolor"}, {"items": [{"name": "Obręcze kół ze stopów lekkich 8J x 19\" Torcular, czarne", "price": "3100 zł"}], "category": "Obręcze kół"}, {"items": [{"name": "Design Selection Suite Sport", "price": null}], "category": "Wnętrze"}, {"items": [{"name": "Pakiet Infotainment Plus", "price": "2500 zł", "components": ["Wyświetlacz Head-up", "Nawigacja", "13\" Wyświetlacz"]}, {"name": "Niezależ