INSERT INTO "public"."ltr_kalkulacje" ("id", "numer_kalkulacji", "status", "stan_json", "dane_pojazdu", "cena_netto", "created_at", "updated_at") VALUES ('e285e90d-b9da-4e3e-9be3-4fbe6e560d29', 'KALK/2026/03/D23BF1', 'szkic_vertex', '{"brand": "CUPRA", "model": "LEON SPORTSTOURER", "toggles": {"gps_required": true, "replacement_car": true, "hook_installation": true, "include_servicing": true, "express_pays_insurance": true}, "discount": {"active_final_price": 198970.99, "active_discount_pct": 27}, "is_metalic": true, "vehicle_id": "6b24982d-26b1-4eda-a9d7-d8356d05073d", "tire_params": {"tire_class": "Premium", "rim_diameter": 19, "tire_count_mode": "auto", "tire_cost_correction": 0, "tire_cost_correction_enabled": true}, "card_summary": {"fuel": "Benzyna", "wheels": "19", "power_hp": null, "emissions": "Brak", "base_price": "222800 PLN brutto", "body_style": "Sportstourer", "drive_type": null, "powertrain": "2.0 TSI 310KM", "trim_level": "Brak", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 222800, "total": 272563, "options": 49763}}, "power_range": null, "total_price": "272563 PLN brutto", "has_tow_hook": true, "paid_options": [{"name": "Dark Void", "price": "5476 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "19-calowe felgi aluminiowe PO-LAR COPPER", "price": "1992 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet SKYLINE", "price": "5476 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet IMMERSIVE dla Pakietu DYNAMIC DESIGN lub PROGRESSIVE DESIGN", "price": "2937 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet INTELLIGENT DRIVE", "price": "3649 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Nawigacja satelitarna z mapami z możliwością aktualizacji", "price": "3303 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet PURE PERFORMANCE", "price": "5996 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Obudowa lusterek bocznych z włókna węglowego w kolorze miedzianym", "price": "3485 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Zewnętrzne listwy progowe CUPRA w kolorze Obsidian Black", "price": "1743 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Hak holowniczy", "price": "3933 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Hamulce wyczynowe z zaciskami BREMBO z przodu w kolorze miedzi", "price": "11773 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Automatyczna", "_price_domain": "brutto", "options_price": "49763 PLN brutto", "vehicle_class": "Osobowy", "exterior_color": "Dark Void 5476 PLN brutto", "engine_capacity": null, "engine_category": null, "is_metalic_paint": true, "utility_features": [], "service_equipment": null, "engine_designation": null, "standard_equipment": [], "financial_reasoning": "Znaleziono sekcję ''Szczegóły dotyczące ceny''. Cena podstawowa: 222.800 zł. Wyposażenie opcjonalne: 49.763 zł. Cena Twojej konfiguracji: 272.563 zł. Sprawdzenie matematyczne: 222.800 + 49.763 = 272.563. Suma zgadza się. Dodatkowo, zsumowano wszystkie pojedyncze opcje płatne: 5.476 + 1.992 + 5.476 + 2.937 + 3.649 + 3.303 + 5.996 + 3.485 + 1.743 + 3.933 + 11.773 = 49.763 zł. Ta suma również zgadza się z podaną ceną wyposażenia opcjonalnego. W sekcji ''Informacje prawne'' znajduje się zapis: ''Prezentowane ceny są wyłącznie cenami rekomendowanymi i obejmują podatek VAT (23%)'', co jednoznacznie wskazuje, że wszystkie podane kwoty są cenami brutto.", "suggested_discount_pct": 27, "is_current_year_vehicle": null, "suggested_discount_source": "Marka CUPRA została dopasowana do ''SEAT/CU