INSERT INTO "public"."vehicle_synthesis" ("id", "brand", "model", "offer_number", "raw_pdf_url", "schema_version", "verification_status", "synthesis_data", "file_hash", "notes", "created_at", "zabudowa_apr_wr", "document_category", "processing_updated_at", "document_markdown") VALUES ('3b7408a3-fbd6-4d28-a9cf-46149a91195f', 'SKODA', 'Scala', NULL, 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/3b7408a3-fbd6-4d28-a9cf-46149a91195f-car-card-C9NTF1S5.pdf', NULL, 'completed', '{"brand": "SKODA", "model": "Scala", "card_summary": {"fuel": "Benzyna", "wheels": "16", "power_hp": 150, "emissions": "Emisja CO2 w cyklu mieszanym 122 g/km / Zużycie paliwa/energii w cyklu mieszanym 5,4 l/100km", "base_price": "117 200 PLN brutto", "body_style": "Hatchback", "drive_type": "Napęd FWD", "powertrain": "1,5 TSI 150 KM 7-biegowa DSG", "trim_level": "Edition 130", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 117200.0, "total": 119950.0, "options": 2750.0}}, "power_range": "MID (131 - 200 KM)", "total_price": "119 950 PLN brutto", "has_tow_hook": null, "paid_options": [{"name": "Biel Moon Metalizowany", "price": "2750 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Automatyczna DSG", "_price_domain": "brutto", "options_price": "2 750 PLN brutto", "vehicle_class": "Osobowy", "exterior_color": "Biel Moon Metalizowany", "engine_capacity": "1.5", "engine_category": "Benzyna (PB)", "is_metalic_paint": true, "utility_features": [], "service_equipment": null, "engine_designation": "TSI", "standard_equipment": ["System alarmowy e-Call", "Škoda Infotainment 8,25\"", "Bluetooth", "4x USB-C z szybkim ładowaniem (45W)", "Zapasowe koło stalowe dojazdowe", "Czołowe i boczne poduszki bezpieczeństwa z przodu, kurtyny powietrzne", "Czujniki parkowana z przodu i tyłu", "Tempomat z ogranicznikiem prędkości", "Cyfrowy zestaw wskaźników Digital Display 8\"", "Smartlink - połączenie bezprzewodowe", "Kamera cofania", "Traffic Sign Recognition - funkcja rozpoznawania znaków drogowych", "Dodatkowe 4 głośniki (z tyłu)", "Climatronic- dwustrefowa klimatyzacja automatyczna", "Usługa Care Connect - Remote Access 3 lata", "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania", "Hill Hold Control - system wspomagania ruszania pod wzniesienia", "Lane Assist - asystent pasa ruchu", "Driver Alert", "DAB + funkcja odbioru programów radiowych w formie cyfrowej", "Automatycznie ściemniające się lusterko wsteczne", "Driving mode select", "Easy light assist - czujnik zmierzchu", "Podgrzewane fotele przednie", "KESSY FULL z funkcją SAFE", "Alarm", "Reflektory Full LED", "Przednie reflektory przeciwmgłowe LED", "Elektrycznie sterowane szyby przednie i tylne", "Tylne światła LED Basic", "Ramka grilla chromowana", "Elektrycznie sterowane i podgrzewane lusterka boczne", "Uchwyty ISOFIX na zewnętrznych miejscach z tyłu oraz na fotelu pasażera z przodu"], "financial_reasoning": "Na stronie 1 dokumentu zidentyfikowano następujące kwoty: ''Twoja konfiguracja'' (cena bazowa) za 117 200 zł, ''Wybrane wyposażenie opcjonalne i usługi'' za 2 750 zł oraz ''Cena widocznej konfiguracji'' (cena całkowita) za 119 950 zł. Sprawdzenie matematyczne potwierdza, że 117 200 zł + 2 750 zł = 119 950 zł. Na stronie 3 znajduje się informacja ''Podane ceny obejmują podatek VAT (23%)'', co jednoznacznie określa domenę cenową jako brutto. W związku z tym, cena bazowa to 117 200 zł brutto, cena opcji to 2 750 zł brutto, a cena całkowita to 119 950 zł brutto.", "suggested_discount_pct": 24.0, "is_current_year_vehicle": true, "suggested_discount_source": "Pojazd SKODA Scala z kodem konfiguracji NW1DPD (znalezionym w dokumencie oferty) dokładnie pasuje do pozycji ''SCALA SELECTION'' (kod NW1D**) w bazie rabatów.", "suggested_discount_confidence": 98}, "digital_twin": {"pages": [{"footer": {"pagination": "Strona 1 / 5"}, "header": {"qr_code": "Obecny kod QR w prawym górnym rogu.", "brand_logo": "SKODA", "saved_date": "Zapisano: 31.03.2025, 12:45", "configuration_id": "ID konfiguracji: C9NTF1S5"}, "visuals": [{"type": "main_image", "description": "Zdjęcie zewnętrzne samochodu Skoda Scala w kolorze białym, widok z przodu, z lewego boku."}, {"type": "interior_image", "description": "Zdjęcie wnętrza pojazdu, widok na deskę rozdzielczą, kierownicę i przednie fotele."}, {"type": "interior_image", "description": "Zdjęcie wnętrza pojazdu, widok na tylne siedzenia."}], "page_number": 1, "pricing_summary": {"items": [{"price": "117 200 zł", "description": "Twoja konfiguracja"}, {"price": "2750 zł", "description": "Wybrane wyposażenie opcjonalne i usługi"}], "title": "Ceny", "total": {"price": "119 950 zł", "description": "Cena widocznej konfiguracji"}, "financing": {"value": "Dostępne wkrótce", "description": "Rata miesięczna *"}}, "vehicle_summary": {"model": "Scala", "version": "Edition 130", "engine_transmission": "1,5 TSI (150 KM) 110 kW 7-biegowa DSG", "emissions_consumption": "Emisja CO2 w cyklu mieszanym 122 g/km / Zużycie paliwa/energii w cyklu mieszanym 5,4 l/100km"}}, {"footer": {"pagination": "Strona 2 / 5"}, "header": {"qr_code": "Obecny kod QR w prawym górnym rogu.", "brand_logo": "SKODA", "saved_date": "Zapisano: 31.03.2025, 12:45", "configuration_id": "ID konfiguracji: C9NTF1S5"}, "page_number": 2, "selected_options": {"items": [{"name": "Biel Moon Metalizowany", "price": "2750 zł", "category": "Kolor"}, {"name": "Obręcze kół ze stopów lekkich Sargas Aero 6J x 16\" - w kolorze srebrnym", "price": "0 zł", "category": "Obręcze kół"}, {"name": "Loft z szarą podsufitką", "price": null, "category": "Wnętrze"}], "title": "Wybrane wyposażenie i usługi"}, "standard_equipment": {"title": "Wyposażenie standardowe", "sections": [{"title": "Komfort, bezpieczeństwo i funkcjonalność", "features": ["System alarmowy e-Call", "Škoda Infotainment 8,25\"", "Bluetooth", "4x USB-C z szybkim ładowaniem (45W)", "Zapasowe koło stalowe dojazdowe", "Czołowe i boczne poduszki bezpieczeństwa z przodu, kurtyny powietrzne", "Czujniki parkowana z przodu i tyłu", "Tempomat z ogranicznikiem prędkości", "Cyfrowy zestaw wskaźników Digital Display 8\"", "Smartlink - połączenie bezprzewodowe dla urządzeń Apple iOS*", "Kamera cofania", "Traffic Sign Recognition - funkcja rozpoznawania znaków drogowych", "Dodatkowe 4 głośniki (z tyłu)", "Climatronic- dwustrefowa klimatyzacja automatyczna", "Usługa Care Connect - Remote Access 3 lata", "Dezaktywacja czołowej poduszki pasażera z przodu", "Sygnalizacja ostrzegawcza niezapiętych pasów bezpieczeństwa", "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania z Pedestrian Monitor", "Hill Hold Control - system wspomagania ruszania pod wzniesienia", "Lane Assist - asystent pasa ruchu", "Driver Alert", "DAB + funkcja odbioru programów radiowych w formie cyfrowej", "Automatycznie ściemniające się lusterko wsteczne", "Driving mode select", "Easy light assist - czujnik zmierzchu", "Podgrzewane fotele przednie", "KESSY FULL z funkcją SAFE", "Alarm"]}, {"title": "Nadwozie", "features": ["Reflektory Full LED", "Przednie reflektory przeciwmgłowe LED", "Elektrycznie sterowane szyby przednie i tylne", "Obręcze kół ze stopów lekkich Sargas Aero 6J x 16\" - w kolorze srebrnym", "Zderzaki w kolorze nadwozia", "Tylne światła LED Basic", "Ramka grilla chromowana", "Elektrycznie sterowane i podgrzewane lusterka boczne"]}]}, "configuration_codes": "KODY NW1DPD/MASGEB1\\GWNAWNA\\GYOKYOK, 2025, HN, 2Y2Y"}, {"footer": {"pagination": "Strona 3 / 5"}, "header": {"qr_code": "Obecny kod QR w prawym górnym rogu.", "brand_logo": "SKODA", "saved_date": "Zapisano: 31.03.2025, 12:45", "configuration_id": "ID konfiguracji: C9NTF1S5"}, "page_number": 3, "legal_disclaimers": {"content": ["Prezentowane są wybrane elementy wyposażenia standardowego. Domówienie pakietu lub opcji może mieć wpływ na wyposażenie standardowe – w niektórych przypadkach bezpowrotnie usuwając lub zastępując elementy.", "Wszelkie prezentowane informacje, w szczególności zdjęcia, wykresy, specyfikacje, opisy, rysunki lub parametry techniczne, nie stanowią oferty w rozumieniu Kodeksu cywilnego oraz nie są wiążące i mogą ulec zmianie bez wcześniejszego powiadomienia. Prezentowane informacje nie stanowią zapewnienia w rozumieniu art. 556(1)§2 Kodeksu cywilnego. Škoda zastrzega sobie możliwość wprowadzenia zmian w prezentowanych wersjach. Przedstawione detale wyposażenia mogą różnić się od specyfikacji przewidzianej na rynek polski. Zamieszczone zdjęcia mogą przedstawiać wyposażenie opcjonalne. Wiążące ustalenie ceny, wyposażenia i specyfikacji pojazdu następuje w umowie sprzedaży, a określenie parametrów technicznych zawiera świadectwo homologacji typu pojazdu. Zastrzegamy sobie prawo do zmian i pomyłek. Wszelkie informacje prezentowane w niniejszym cenniku są aktualne na dzień publikacji materiału.", "W celu uzyskania najnowszych informacji prosimy kontaktować się z Autoryzowanym Dealerem Marki Škoda Podane ceny obejmują podatek VAT (23%).", "Z uwagi na ograniczenia technik drukarskich lub parametrów ekranu, na którym obraz jest wyświetlany, kolory przedstawione w niniejszym materiale mogą nieznacznie różnić się od faktycznych kolorów lakieru i materiałów.", "W celu uzyskania najnowszych informacji prosimy kontaktować się z Autoryzowanym Dealerem Marki Škoda.", "Wszystkie produkowane obecnie samochody marki Škoda są wykonywane z materiałów spełniających pod względem możliwości odzysku i recyklingu wymagania określone w normie ISO 22628 i są zgodne z europejskimi świadectwami homologacji wydanymi wg dyrektywy 2005/64/WE. Volkswagen Group Polska sp. z o.o. podlega obowiązkowi zapewnienia wszystkim użytkownikom samochodów marki Škoda sieci odbioru pojazdów po wycofaniu ich z eksploatacji, zgodnie z wymaganiami ustawy z 20 stycznia 2005 r. o recyklingu pojazdów wycofanych z eksploatacji.", "Więcej informacji dotyczących ekologii znajdą Państwo na stronach: www.skoda-auto.pl/technologia/dbamy-o-srodowisko, www.skoda-auto.pl .", "Od 1 września 2018 r. wszystkie nowe pojazdy wprowadzane do obrotu w Unii Europejskiej muszą być badane i homologowane zgodnie z procedurą WLTP określoną w rozporządzeniu Komisji (UE) 2017/1151. Prezentowane dane dotyczące wartości zużycia paliwa/energii, emisji CO2 lub zasięgu są danymi zgodnymi ze świadectwem homologacji typu wyznaczonymi zgodnie z procedurą WLTP.", "Montaż akcesoriów w pojeździe może mieć wpływ na poziom zużycia paliwa/energii, emisję CO2 lub zasięg oraz może nastąpić najwcześniej po pierwszej rejestracji pojazdu, wyłącznie na Państwa życzenie.", "Škoda Connect", "Korzystanie z usług Škoda Connect (zwanych dalej „Usługami”) wymaga zawarcia osobnej umowy przez Internet z firmą Škoda Auto, a.s. W celu skorzystania z maksymalnego czasu trwania usługi klient musi w ciągu 90 dni zarejestrować pojazd, np. za pośrednictwem portalu internetowego https://www.skoda-auto.pl/serwis/connect lub aplikacji mobilnej https://www.skoda-auto.pl/swiat-skody/myskoda-app bądź za pośrednictwem systemu infotainment w pojeździe po dostarczeniu pojazdu.", "Nie ma potrzeby rejestracji usługi Połączenia Alarmowego/eCall - jest ona aktywna od momentu dostawy.", "Dostępność Usług może się różnić w zależności od kraju, modelu pojazdu, roku modelowego i wyposażenia Pojazdu. Opisane Usługi mogą być dostępne w późniejszym czasie po przekazaniu samochodu. Usługi mogą być obsługiwane tylko przy użyciu dostępnych technologii komunikacji publicznej. Należy pamiętać, że ze względu na rozwój tych technologii, zwłaszcza sieci komórkowych, Škoda Auto nie może zagwarantować stałej dostępności we wszystkich krajach na czas trwania Usług. Ewentualne zmiany technologii mogą spowodować ich trwałą niedostępność.", "W przypadku korzystania z Usług niezbędne jest również połączenie do transmisji danych pomiędzy urządzeniem Klienta (smartfon, tablet, komputer PC itp.) a serwerem danych. To połączenie do transmisji danych nie wchodzi w skład Usług."]}, "standard_equipment_continuation": {"title": "Wnętrze", "features": ["Uchwyty ISOFIX na zewnętrznych miejscach z tyłu oraz na fotelu pasażera z przodu"]}}, {"footer": {"pagination": "Strona 4 / 5"}, "header": {"qr_code": "Obecny kod QR w prawym górnym rogu.", "brand_logo": "SKODA", "saved_date": "Zapisano: 31.03.2025, 12:45", "configuration_id": "ID konfiguracji: C9NTF1S5"}, "page_number": 4, "manufacturer_information": {"email": "e-mail: biuro.vgpl1@vw-group.pl", "title": "Informacje o producencie i informacje o produkcie:", "company": "Škoda Auto a.s. tr. Wacława Klementa 869 293 01 Mladá Boleslav Czechy", "manuals_link": "Instrukcja obsługi zawierająca informacje dotyczące bezpieczeństwa: https://www.skoda-auto.pl/apps/manuals/Models"}, "legal_disclaimers_continuation": {"content": ["Szczegółowe informacje o usługach Škoda Connect i zapewnianych przez nie korzyściach zostały podane na stronie https://www.skoda-auto.pl/serwis/connect lub skontaktuj się z partnerem Škoda.", "Zasięg dla samochodów elektrycznych lub zasięg w trybie elektrycznym dla hybryd typu Plug-In może się różnić w zależności od wersji, wyposażenia oraz zamontowanych akcesoriów, stylu jazdy, prędkości, korzystania z dodatkowych odbiorników energii, temperatury zewnętrznej, liczby pasażerów, obciążenia ładunkiem i topografii terenu. Podana maksymalna moc układu napędowego w przypadku samochodów elektrycznych lub hybryd typu Plug-In jest możliwa do uzyskania tylko w określonych warunkach.", "Na dostępną moc układu napędowego wpływa szereg czynników takich jak temperatura otoczenia, poziom naładowania akumulatora, jego temperatura czy stopień zużycia.", "SmartLink oferuje możliwość obsługi i wyświetlania na ekranie systemu Infotainment certyfikowanych aplikacji (poprzez Android Auto lub Apple CarPlay) zainstalowanych na smartfonie podłączonym za pomocą przewodu USB (dla urządzeń z systemem Android i Apple iOS) lub bezprzewodowo (dla urządzeń z systemem Apple iOS). Działanie SmartLink uzależnione jest od wersji oprogramowania i modelu smartfona. Więcej informacji można uzyskać na stronie https://compatibilitylist.skoda-auto.com"]}}, {"footer": {"pagination": "Strona 5 / 5"}, "header": {"qr_code": "Obecny kod QR w prawym górnym rogu.", "brand_logo": "SKODA", "saved_date": "Zapisano: 31.03.2025, 12:45", "configuration_id": "ID konfiguracji: C9NTF1S5"}, "page_number": 5, "tire_label_section": {"tires": [{"id": "13233", "size": "205/55 R16", "brand": "Bridgestone", "class": "C1", "label": {"wet_grip": "A", "noise_class": "B", "noise_level_db": "71 dB", "fuel_efficiency": "A"}, "details": "BRIDGESTONE 205/55 R16 91 V", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/sWGJNN+ucsA7/smPFGsBrA=="}, {"id": "577215", "size": "205/55 R16", "brand": "GOODYEAR", "class": "C1", "label": {"wet_grip": "B", "noise_class": "A", "noise_level_db": "68 dB", "fuel_efficiency": "A"}, "details": "GOODYEAR 205/55R16 91 V", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/Rmq27gKQ5bXKoVCOc8wkfw=="}, {"id": "18133", "size": "205/55 R16", "brand": "Nexen", "class": "C1", "label": {"wet_grip": "A", "noise_class": "A", "noise_level_db": "69 dB", "fuel_efficiency": "A"}, "details": "NEXENTIRE 205/55R16 91 V", "qr_code_info": "Zeskanuj kod QR przy pomocy swojego smartfona i sprawdź kartę informacyjną.", "product_info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/AYwp90LpV5IBJDzfYWPouA=="}], "title": "Etykieta opony", "subtitle": "Obręcze kół ze stopów lekkich Sargas Aero 6J x 16\" - w kolorze srebrnym", "legal_note": "Zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2020/740 z dnia 25 maja 2020 r. w sprawie etykietowania opon pod kątem efektywności paliwowej i innych parametrów, zmieniające rozporządzenie (UE) 2017/1369 oraz uchylające rozporządzenie (WE) nr 1222/2009 – na stronie znajduje się lista etykiet opon wraz z dostępem do kart informacyjnych produktu (do pobrania po kliknięciu w etykietę), która przedstawia opony, jakie potencjalnie mogą być zamontowane w Twoim samochodzie. Ze względów logistycznych i produkcyjnych nie ma możliwości wyboru danej opony od konkretnego producenta opon. Więcej informacji na temat opon można uzyskać u Autoryzowanego Dealera Marki SKODA."}}], "metadata": {"document_type": "Oferta na samochód"}, "document_metadata": {"data_zapisu": "31.03.2025, 12:45", "liczba_stron": 5, "id_konfiguracji": "C9NTF1S5"}}, "offer_number": null, "mapped_ai_data": {"fuel": "Benzyna (PB)", "brand": "SKODA", "model": "Scala", "trim_level": "Edition 130", "engine_class": "spalinowy", "transmission": "Automatyczna DSG", "vehicle_type": "Osobowy", "samar_category": "Podstawowa - C NIŻSZA ŚREDNIA", "samar_candidates": [{"klasa": "Podstawowa - C NIŻSZA ŚREDNIA", "confidence": 1.0}, {"klasa": "Podstawowa - B MAŁE", "confidence": 0.2}, {"klasa": "Podstawowa - A MINI", "confidence": 0.05}], "engine_candidates": [{"klasa": "Benzyna (PB)", "confidence": 0.95}, {"klasa": "Benzyna mHEV (PB-mHEV)", "confidence": 0.03}]}, "configuration_code": "C9NTF1S5", "_extraction_metadata": {"model": "gemini-2.5-pro", "stage": "digital_twin", "output_tokens": 4716, "prompt_tokens": 2436, "thinking_tokens": 6603}}'::jsonb, '846aea80181342c374093cf43dac1bdf', NULL, '2026-03-12T08:45:52.789954+00:00', FALSE, 'Osobowy', '2026-03-12T08:50:01.532165+00:00', NULL);
