INSERT INTO "public"."vehicle_synthesis" ("id", "brand", "model", "offer_number", "raw_pdf_url", "schema_version", "verification_status", "synthesis_data", "file_hash", "notes", "created_at", "zabudowa_apr_wr", "document_category", "processing_updated_at", "document_markdown") VALUES ('40140a56-c592-4ca6-a5bd-245920b5fab3', 'Toyota', 'PROACE CITY / PROACE CITY VERSO', '134/2024/06/1066', 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/40140a56-c592-4ca6-a5bd-245920b5fab3-EXPRESS_SP._Z_O.O._SP._K._6770046633_TwojaToyota_2024_06_26_162309.pdf', NULL, 'completed', '{"brand": "Toyota", "model": "PROACE CITY / PROACE CITY VERSO", "card_summary": {"fuel": "Diesel", "wheels": "16", "power_hp": 100, "emissions": "145 g/km, 5.5 l/100km", "base_price": "109 800 PLN netto", "body_style": "Furgon", "drive_type": "Napęd FWD", "powertrain": "1.5 D-4D 100 KM diesel", "trim_level": "Active", "_validation": {"summary": {"details": "Cena bazowa jest wyższa od łącznej. Po zamianie pól arytmetyka się zgadza.", "verdict": "Prawdopodobna zamiana pól base↔total", "confidence": "LOW", "suggestions": ["Zamień wartości base_price i total_price"]}, "is_valid": false, "warnings": [{"rule": "BASE_PLUS_OPTIONS_VS_TOTAL", "actual": 76440.0, "message": "baza(109800) + opcje(7800) = 117600, ale total = 76440 (Δ 41160 / 35.0%)", "diff_pct": 35.0, "expected": 117600.0, "severity": "ERROR"}, {"rule": "BASE_TOTAL_SWAPPED", "actual": 109800.0, "message": "base(109800) > total(76440) — kolejność cen może być odwrócona", "expected": 76440.0, "severity": "WARNING"}], "parsed_prices": {"base": 109800.0, "total": 76440.0, "options": 7800.0}}, "power_range": "LOW (do 130 KM)", "total_price": "76 440 PLN netto", "has_tow_hook": null, "paid_options": [{"name": "Multimedia", "price": "5 500 PLN netto", "category": "Fabryczna", "price_type": "netto"}, {"name": "Pakiet siedzeń Active 3", "price": "2 300 PLN netto", "category": "Fabryczna", "price_type": "netto"}], "price_domain": "netto", "transmission": "6-stopniowa manualna", "_price_domain": "netto", "options_price": "7 800 PLN netto", "vehicle_class": "Dostawczy", "exterior_color": "Icy White", "engine_capacity": "1.5", "engine_category": "Diesel (ON)", "is_metalic_paint": false, "service_equipment": null, "engine_designation": "D-4D", "standard_equipment": ["Automatyczne światła z czujnikiem zmierzchu", "Automatyczny ogranicznik prędkości (ASL)", "Elektrycznie regulowane szyby z zabezpieczeniem przed przycięciem palców", "Elektryczny hamulec postojowy", "Hamulec ręczny", "System Stop&Start", "System automatycznego powiadamiania ratunkowego (eCall)", "System monitorowania ciśnienia w oponach (TPMS)", "System stabilizacji toru jazdy (VSC)", "System wspomagający hamowanie (BA)", "System wspomagający pokonywanie podjazdów (HAC)", "System wspomagający zjazd ze wzniesienia (DAC)", "System zapobiegający blokowaniu kół (ABS) z elektronicznym rozkładem sił hamowania (EBD)", "Tempomat", "Manualna regulacja fotela kierowcy", "Tapicerka materiałowa", "Pełnowymiarowe koło zapasowe", "Standardowe dekielki felg", "Centralny zamek", "Chłodzony schowek", "Elektrycznie regulowane lusterka zewnętrzne", "Elektrycznie regulowane szyby przednie", "Filtr kabinowy", "Klimatyzacja manualna", "Manualnie składane lusterka zewnętrzne", "Podgrzewane lusterka zewnętrzne", "Przednie oświetlenie nad fotelem kierowcy i pasażera", "Przednie uchwyty na butelki", "Uchwyt na butelkę o pojemności 0,5 litra", "Uruchamianie silnika za pomocą kluczyka", "Wskaźnik wyboru optymalnego biegu dla skrzyni manualnej (GSI)", "Drzwi boczne przesuwane z prawej strony", "Drzwi z kątem otwarcia 180°", "Listwy ochronne w drzwiach bocznych w kolorze czarnym", "Otwarty schowek w konsoli centralnej", "Przegroda nieprzeszklona", "Tylne drzwi skrzydłowe panelowe", "Światła do jazdy dziennej", "Analogowy prędkościomierz", "Antena dachowa", "Górny przedni grill w kolorze czarnym", "Klamki zewnętrzne w kolorze czarnym", "Krótka antena", "Przedni zderzak w kolorze czarnym", "Tylny zderzak w kolorze czarnym", "2 głośniki", "Kolorowy wyświetlacz na tablicy wskaźników (rozmiar standardowy)", "Port USB", "Radio", "System Bluetooth® umożliwiający bezprzewodową łączność z telefonem", "Analogowy obrotomierz", "Chromowane wykończenie gałki dźwigni zmiany biegów", "Gałka dźwigni zmiany biegów wykonana z uretanu", "Klamki wewnętrzne w kolorze czarnym", "Oświetlenia wnętrza z przodu", "Trójramienna kierownica z uretanu"], "financial_reasoning": "Dla modelu TOYOTA PROACE CITY - MY22:\n1. Zidentyfikowano następujące kwoty:\n   - Cena wybranej wersji wyposażenia: 109 800 zł\n   - Multimedia: 5 500 zł\n   - Pakiet siedzeń Active 3: 2 300 zł\n   - Cena całkowita (katalogowa): 117 600 zł\n   - Całkowita wartość udzielonego rabatu: -41 160 zł\n   - Cena specjalna: 76 440 zł\n2. W dokumencie na stronie 3 wyraźnie zaznaczono: \"Wszystkie podane ceny są cenami netto.\", co ustala domenę cenową na ''netto''.\n3. Weryfikacja relacji matematycznych:\n   - Cena bazowa (wersja wyposażenia) = 109 800 PLN netto.\n   - Suma opcji płatnych = Multimedia (5 500 PLN netto) + Pakiet siedzeń Active 3 (2 300 PLN netto) = 7 800 PLN netto.\n   - Cena bazowa + Opcje = 109 800 PLN netto + 7 800 PLN netto = 117 600 PLN netto. Ta kwota zgadza się z ''Cena całkowita'' oraz ''Całkowita cena katalogowa'' w dokumencie.\n   - Cena całkowita katalogowa - Rabat = 117 600 PLN netto - 41 160 PLN netto = 76 440 PLN netto. Ta kwota zgadza się z ''Cena specjalna''.\n4. Wszystkie kwoty są spójne i matematycznie poprawne. Rabat jest wyraźnie oddzielony od ceny katalogowej i opcji.", "suggested_discount_pct": 35, "is_current_year_vehicle": false, "suggested_discount_source": "Rabat flotowy -35% z sekcji ''Flota'' na stronie 3."}, "digital_twin": {"pages": [{"content": [{"type": "header", "content": {"logo": "Toyota logo", "valid_until": "Ważna do 26.07.2024", "date_of_issue": "Z dnia 26.06.2024", "calculation_number": "Kalkulacja nr 134/2024/06/1066"}}, {"text": "TOYOTA BUSINESS", "type": "title", "level": 1}, {"text": "Specjalna kalkulacja flotowa wybranych przez Państwa modeli", "type": "subtitle"}, {"body": ["Toyota stworzyła unikalny program sprzedaży i obsługi posprzedażnej Toyota Business przygotowany z myślą o Klientach biznesowych. Głównym założeniem programu jest indywidualne podejście oraz dostosowywanie naszej szerokiej oferty do indywidualnych potrzeb każdego Klienta.", "Najważniejszym celem, dla którego tworzymy i wdrażamy nowe produkty jest uzyskanie maksymalnej satysfakcji Klientów. Nasze samochody oprócz niezapomnianych wrażeń z jazdy gwarantują niespotykaną u konkurencji jakość, niezawodność a także jedne z najwyższych wartości rezydualnych.", "Niniejsza oferta zawiera szczegółowe informacje dotyczące wyposażenia, cen specjalnych oraz terminów realizacji zamówienia wybranych samochodów marki Toyota. W każdej chwili może zostać uzupełniona o dodatkowe modele bądź specyfikacje.", "Opieka serwisowa Państwa parku samochodowego będzie realizowana z najwyższą dbałością w ramach programu Toyota Business Service.", "We wszystkich kwestiach związanych z naszą ewentualną współpracą pozostaję do Państwa dyspozycji."], "type": "letter", "closing": {"name": "Jacek Nowakowski", "email": "jacek.nowakowski@toyota-romanowski.pl", "salutation": "Z poważaniem,"}, "greeting": "Szanowni Państwo,"}, {"type": "contact_details", "prepared_by": {"name": "Jacek Nowakowski", "email": "jacek.nowakowski@toyota-romanowski.pl", "title": "Kto przygotował kalkulację", "address": "31-476 Kraków, ul. Zakopiańska 68", "company": "TOYOTA ROMANOWSKI KRAKÓW"}, "prepared_for": {"nip": "6770046633", "email": "autoryzacje@express.pl", "phone": "+48 667071705", "title": "Dla kogo przygotowano kalkulację", "company": "EXPRESS SP. Z O.O. SP. K."}}, {"text": "Toyota Central Europe rezerwuje sobie prawo do zmian oferty, w szczególności zmian cen, specyfikacji, wyposażenia i dostępności pojazdów bez uprzedzenia. Prezentowane zdjęcie ma charakter poglądowy. Najniższe ceny rekomendowane z ostatnich 30 dni są dostępne w cennikach poszczególnych modeli na stronie www.toyota.pl oraz www.lexus-polska.pl", "type": "footer"}], "page_number": 1}, {"content": [{"type": "header", "content": {"logo": "Toyota logo", "valid_until": "Ważna do 26.07.2024", "date_of_issue": "Z dnia 26.06.2024", "calculation_number": "Kalkulacja nr 134/2024/06/1066"}}, {"text": "TOYOTA", "type": "title", "level": 1}, {"text": "Wybrane przez Państwa modele flotowe", "type": "subtitle"}, {"type": "vehicle_summary", "vehicle": {"model": "PROACE CITY - MY22", "details": [{"label": "Wybrany model", "value": "PROACE CITY - MY22"}, {"label": "Cena specjalna", "value": "76 440 PLN (netto)"}, {"label": "Liczba samochodów flotowych", "value": "1"}, {"label": "Nadwozie", "value": "Furgon Long pojedyncze drzwi boczne"}, {"label": "Silnik", "value": "1.5 D-4D 100 KM diesel"}, {"label": "Skrzynia biegów", "value": "6-stopniowa manualna"}, {"label": "Wersja", "value": "Active"}], "image_description": "Zdjęcie szarego samochodu dostawczego Toyota PROACE CITY, widok z przodu z boku."}}, {"type": "vehicle_summary", "vehicle": {"model": "Proace City Verso - MC24", "details": [{"label": "Wybrany model", "value": "Proace City Verso - MC24"}, {"label": "Cena specjalna", "value": "103 575 PLN (brutto)"}, {"label": "Liczba samochodów flotowych", "value": "1"}, {"label": "Nadwozie", "value": "Nadwozie Long podwójne drzwi boczne"}, {"label": "Silnik", "value": "1.5 D4-D diesel 100 KM"}, {"label": "Skrzynia biegów", "value": "6-stopniowa manualna"}, {"label": "Wersja", "value": "Combi"}], "image_description": "Zdjęcie ciemnozielonego samochodu osobowego Toyota Proace City Verso, widok z przodu z boku."}}, {"text": "Toyota Central Europe rezerwuje sobie prawo do zmian oferty, w szczególności zmian cen, specyfikacji, wyposażenia i dostępności pojazdów bez uprzedzenia. Prezentowane zdjęcie ma charakter poglądowy. Najniższe ceny rekomendowane z ostatnich 30 dni są dostępne w cenn