INSERT INTO "public"."vehicle_synthesis" ("id", "brand", "model", "offer_number", "raw_pdf_url", "schema_version", "verification_status", "synthesis_data", "file_hash", "notes", "created_at", "zabudowa_apr_wr", "document_category", "processing_updated_at", "document_markdown") VALUES ('4c2e9a33-a793-47fe-95ff-7a9f789a16b1', 'Renault', 'ESPACE', NULL, 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/4c2e9a33-a793-47fe-95ff-7a9f789a16b1-ESPACE_esprit_Alpine_ETech_full_hybrid_200__1___2_.pdf', NULL, 'completed', '{"brand": "Renault", "model": "ESPACE", "card_summary": {"fuel": "Hybryda (HEV)", "wheels": "20", "power_hp": 200, "emissions": "106 g/km, 4.7 l/100km", "base_price": "206 900 PLN brutto", "body_style": "SUV", "drive_type": "Napęd FWD", "powertrain": "1.2 E-Tech full hybrid 200 KM", "trim_level": "esprit Alpine", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 206900, "total": 226200, "options": 19300}}, "power_range": "MID (131 - 200 KM)", "total_price": "226 200 PLN brutto", "has_tow_hook": null, "paid_options": [{"name": "czarny etoile", "price": "3000 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "panoramiczny szklany dach", "price": "4500 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "pakiet winter comfort", "price": "4800 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "światła przednie full LED Matrix vision", "price": "4000 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "pakiet advanced driving assist", "price": "3000 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Automatyczna", "_price_domain": "brutto", "options_price": "19 300 PLN brutto