sible_tires": [{"id": "2267663", "size": "205/60 R16", "class": "C1", "model": "PS71", "info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/2ufO20yE0gb/vD/Dg5XFOg==", "manufacturer": "Kumho", "noise_level_db": 71, "wet_grip_class": "A", "load_speed_index": "92 V", "noise_level_class": "B", "visual_description": "Etykieta opony Kumho PS71 z klasami A dla efektywności paliwowej, A dla przyczepności na mokrej nawierzchni i poziomem hałasu 71dB (klasa B).", "fuel_efficiency_class": "A"}, {"id": "546288", "size": "205/60 R16", "class": "C1", "model": null, "info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/o5qhRnkrfHo+LfkrCEqLvg==", "manufacturer": "Goodyear", "noise_level_db": 71, "wet_grip_class": "B", "load_speed_index": "92 V", "noise_level_class": "B", "visual_description": "Etykieta opony Goodyear z klasami A dla efektywności paliwowej, B dla przyczepności na mokrej nawierzchni i poziomem hałasu 71dB (klasa B).", "fuel_efficiency_class": "A"}, {"id": "1028694", "size": "205/60 R16", "class": "C1", "model": null, "info_url": "https://relasdata.blob.core.windows.net/relas/tyres/sheet/nLrnXtqSh+biGPP2vTT05Q==", "manufacturer": "Hankook", "noise_level_db": 68, "wet_grip_class": "A", "load_speed_index": "92 V", "noise_level_class": "A", "visual_description": "Etykieta opony Hankook z klasami A dla efektywności paliwowej, A dla przyczepności na mokrej nawierzchni i poziomem hałasu 68dB (klasa A).", "fuel_efficiency_class": "A"}], "wheel_description": "Obręcze kół ze stopów lekkich Matar Aero 7J x 16\""}, "document_metadata": {"page_count": 7, "saved_date": "30.07.2025, 14:59", "configuration_id": "CPB96GQH"}, "selected_equipment": {"items": [{"name": "Biel Moon Metalizowany", "price": "2650 zł", "category": "Kolor"}, {"name": "Obręcze kół ze stopów lekkich Matar Aero 7J x 16\"", "price": "0 zł", "category": "Obręcze kół"}, {"name": "Studio", "price": null, "category": "Wnętrze"}, {"name": "Schowki w bagażniku po obu stronach", "price": "100 zł", "category": "Funkcjonalność"}], "title": "Wybrane wyposażenie i usługi", "internal_codes": "PV5BCD/MASGEB1\\GYOKYOK, 2026, YD, 2Y2Y, MKKR3N3, GPFXPFX, GPLLPLL", "recommended_packages": [{"name": "Pakiet Fleet", "price": "3200 zł", "contents": ["SmartLink - połączenie przewodowe/bezprzewodowe dla urządzeń Apple iOS", "4 USB - C oraz gniazdo USB przy lusterku wstecznym", "Podłokietnik z przodu", "Schowek w konsoli centralnej zamykany"]}, {"name": "Pakiet Light&View", "price": "2800 zł", "contents": ["Kamera cofania", "Tylne światła LED TOP z dynamicznymi kierunkowskazami"]}]}, "standard_equipment": {"title": "Wyposażenie standardowe", "sections": [{"name": "Komfort, bezpieczeństwo i funkcjonalność", "items": ["Reflektory LED Basic", "Infotainment 10\"", "Attention and Drowsiness Assist - funkcja wykrywania zmęczenia kierowcy", "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania oraz Collision Avoidance Assist", "Light and Rain Assist - czujnik zmierzchu i deszczu", "Lane Assist - asystent pasa ruchu", "Climatronic - automatyczna klimatyzacja dwustrefowa z regulacją elektroniczną", "Elektrycznie składane lusterka boczne, automatycznie przyciemniające się lusterko po stronie kierowcy", "Boczne poduszki powietrzne z centralną poduszką powietrzną", "Czołowe poduszki bezpieczeństwa kierowcy i pasażera z przodu, dezaktywacja poduszki bezpieczeństwa pasażera z przodu, poduszka kolanowa kierowcy", "Automatycznie ściemniające się lusterko wsteczne z czujnikiem wilgotności", "8 głośników", "Turn Assist - asystent skrętu", "Rozpoznawanie znaków drogowych", "HHC - Hill-hold control", "Tempomat", "TPM - system kontroli ciśnienia w oponach", "DAB+ - cyfrowy odbiór stacji radiowych", "Inteligentny ogranicznik prędkości", "Side Assist - funkcja monitorowania martwego pola z Rear Traffic Alert i Exit Warning", "Sygnalizacja ostrzegawcza niezapiętych pasów bezpieczeństwa", "Crossroad Assist"]}, {"name": "Nadwozie", "items": ["Lusterka boczne i klamki w kolorze nadwozia", "Elektrycznie sterowane szyby przednie i tylne", "Obręcze kół ze stopów lekkich Matar Aero 7J x 16\""]}, {"name": "Wnętrze", "items": ["Skórzana 2-ramienna kierownica wielofunkcyjna z manetkami", "Fotel kierowcy i pasażera regulowany na wysokość wraz z regulacją pod lędźwie", "Uchwyty Isofix na zewnętrznych miejscach z tyłu oraz na fotelu pasażera z przodu", "Oświetlenie części bagażowej - 2 lampki", "Gniazdo 12V w bagażniku"]}]}, "legal_and_service_information": {"sections": [{"title": "General Disclaimers", "content": "Prezentowane są wybrane elementy wyposażenia standardowego. Domówienie pakietu lub opcji może mieć wpływ na wyposażenie standardowe – w niektórych przypadkach bezpowrotnie usuwając lub zastępując elementy. Wszelkie prezentowane informacje, w szczególności zdjęcia, wykresy, specyfikacje, opisy, rysunki lub parametry techniczne, nie stanowią oferty w rozumieniu Kodeksu cywilnego oraz nie są wiążące i mogą ulec zmianie bez wcześniejszego powiadomienia. Prezentowane informacje nie stanowią zapewnienia w rozumieniu art. 556(1)§2 Kodeksu cywilnego. Škoda zastrzega sobie możliwość wprowadzenia zmian w prezentowanych wersjach. Przedstawione detale wyposażenia mogą różnić się od specyfikacji przewidzianej na rynek polski. Zamieszczone zdjęcia mogą przedstawiać wyposażenie opcjonalne. Wiążące ustalenie ceny, wyposażenia i specyfikacji pojazdu następuje w umowie sprzedaży, a określenie parametrów technicznych zawiera świadectwo homologacji typu pojazdu. Zastrzegamy sobie prawo do zmian i pomyłek. Wszelkie informacje prezentowane w niniejszym cenniku są aktualne na dzień publikacji materiału. W celu uzyskania najnowszych informacji prosimy kontaktować się z Autoryzowanym Dealerem Marki Škoda Podane ceny obejmują podatek VAT (23%). Z uwagi na ograniczenia technik drukarskich lub parametrów ekranu, na którym obraz jest wyświetlany, kolory przedstawione w niniejszym materiale mogą nieznacznie różnić się od faktycznych kolorów lakieru i materiałów. W celu uzyskania najnowszych informacji prosimy kontaktować się z Autoryzowanym Dealerem Marki Škoda. Wszystkie produkowane obecnie samochody marki Škoda są wykonywane z materiałów spełniających pod względem możliwości odzysku i recyklingu wymagania określone w normie ISO 22628 i są zgodne z europejskimi świadectwami homologacji wydanymi wg dyrektywy 2005/64/WE. Volkswagen Group Polska sp. z o.o. podlega obowiązkowi zapewnienia wszystkim użytkownikom samochodów marki Škoda sieci odbioru pojazdów po wycofaniu ich z eksploatacji, zgodnie z wymaganiami ustawy z 20 stycznia 2005 r. o recyklingu pojazdów wycofanych z eksploatacji. Więcej informacji dotyczących ekologii znajdą Państwo na stronach: www.skoda-auto.pl/technologia/dbamy-o-srodowisko, www.skoda-auto.pl. Od 1 września 2018 r. wszystkie nowe pojazdy wprowadzane do obrotu w Unii Europejskiej muszą być badane i homologowane zgodnie z procedurą WLTP określoną w rozporządzeniu Komisji (UE) 2017/1151. Prezentowane dane dotyczące wartości zużycia paliwa/energii, emisji CO2 lub zasięgu są danymi zgodnymi ze świadectwem homologacji typu wyznaczonymi zgodnie z procedurą WLTP. * Dane techniczne pojazdu, w tym dane wltp mogą różnić się w zależności od tygodnia produkcji. O szczegóły zapytaj u Partnerów Marki Škoda. Montaż akcesoriów w pojeździe może mieć wpływ na poziom zużycia paliwa/energii, emisję CO2 lub zasięg oraz może nastąpić najwcześniej po pierwszej rejestracji pojazdu, wyłącznie na Państwa życzenie. Škoda Connect"}, {"title": "Škoda Connect Terms", "content": "Korzystanie z usług Škoda Connect (zwanych dalej „Usługami”) wymaga zawarcia osobnej umowy przez Internet z firmą Škoda Auto, a.s. W celu skorzystania z maksymalnego czasu trwania usługi klient musi w ciągu 90 dni zarejestrować pojazd, np. za pośrednictwem portalu internetowego https://www.skoda-auto.pl/serwis/connect lub aplikacji mobilnej https://www.skoda-auto.pl/swiat-skody/myskoda-app bądź za pośrednictwem systemu infotainment w pojeździe po dostarczeniu pojazdu. Nie ma potrzeby rejestracji usługi Połączenia Alarmowego/eCall - jest ona aktywna od momentu dostawy. Dostępność Usług może się różnić w zależności od kraju, modelu pojazdu, roku modelowego i wyposażenia Pojazdu. Opisane Usługi mogą być dostępne w późniejszym czasie po przekazaniu samochodu. Usługi mogą być obsługiwane tylko przy użyciu dostępnych technologii komunikacji publicznej. Należy pamiętać, że ze względu na rozwój tych technologii, zwłaszcza sieci komórkowych, Škoda Auto nie może zagwarantować stałej dostępności we wszystkich krajach na czas trwania Usług. Ewentualne zmiany technologii mogą spowodować ich trwałą niedostępność. W przypadku korzystania z Usług niezbędne jest również połączenie do transmisji danych pomiędzy urządzeniem Klienta (smartfon, tablet, komputer PC itp.) a serwerem danych. To połączenie do transmisji danych nie wchodzi w skład Usług. Szczegółowe informacje o usługach Škoda Connect i zapewnianych przez nie korzyściach zostały podane na stronie https://www.skoda-auto.pl/serwis/connect lub skontaktuj się z partnerem Škoda. Zasięg dla samochodów elektrycznych lub zasięg w trybie elektrycznym dla hybryd typu Plug-In może się różnić w zależności od wersji, wyposażenia oraz zamontowanych akcesoriów, stylu jazdy, prędkości, korzystania z dodatkowych odbiorników energii, temperatury zewnętrznej, liczby pasażerów, obciążenia ładunkiem i topografii terenu. Podana maksymalna moc układu napędowego w przypadku samochodów elektrycznych lub hybryd typu Plug-In jest możliwa do uzyskania tylko w określonych warunkach. Na dostępną moc układu napędowego wpływa szereg czynników takich jak temperatura otoczenia, poziom naładowania akumulatora, jego temperatura czy stopień zużycia. SmartLink oferuje możliwość obsługi i wyświetlania na ekranie systemu Infotainment certyfikowanych aplikacji (poprzez Android Auto lub Apple CarPlay) zainstalowanych na smartfonie podłączonym za pomocą przewodu USB (dla urządzeń z systemem Android i Apple iOS) lub bezprzewodowo (dla urządzeń z systemem Apple iOS). Działanie SmartLink uzależnione jest od wersji oprogramowania i modelu smartfona. Więcej informacji można uzyskać na stronie https://compatibilitylist.skoda-auto.com"}, {"title": "Producer and Product Information", "content": "Informacje o producencie i informacje o produkcie: Škoda Auto a.s. tr. Wacława Klementa 869 293 01 Mladá Boleslav Czechy e-mail: biuro.vgpl1@vw-group.pl Instrukcja obsługi zawierająca informacje dotyczące bezpieczeństwa: https://www.skoda-auto.pl/apps/manuals/Models"}, {"title": "INFORMACJE O DOSTĘPNOŚCI", "content": "Niniejsze informacje o dostępności zostały zebrane przez Škoda Auto a.s. (zwaną dalej „my”) zgodnie z Dyrektywą (UE) 2019/882 Parlamentu Europejskiego i Rady z dnia 17 kwietnia 2019 r. w sprawie wymogów dostępności produktów i usług oraz Ustawą nr 424/2023 Dz.U. w sprawie wymogów dostępności niektórych produktów i usług, ze zmianami (zwaną dalej „Ustawą o wymogach dostępności”). Chcemy, aby nasze usługi cyfrowe były dostępne dla szerokiego grona klientów, w tym osób niepełnosprawnych i z innymi ograniczeniami funkcjonalnymi. Z tego powodu stale aktualizujemy nasze usługi, aby były zgodne z wymogami dostępności na mocy obowiązujących przepisów, norm, specyfikacji technicznych i najnowszych wymogów najlepszych praktyk. Niniejsze informacje o dostępności zapewniają ogólny przegląd sposobu działania naszych usług, opisują, w jaki sposób spełniamy wymogi dostępności, i zawierają dane kontaktowe dla wszystkich, którzy mają pytania dotyczące dostępności naszych usług. Informacje te są udostępniane zgodnie z § 14 Ustawy o wymogach dostępności.", "subsections": [{"title": "A. OGÓLNY OPIS USŁUG", "content": "Jesteśmy dostawcą usług e-commerce w rozumieniu Ustawy o wymogach dostępności. Oznacza to, że nasza firma może zawrzeć z Tobą umowę na odległość za pośrednictwem naszej strony internetowej lub aplikacji mobilnych bez Twojej fizycznej obecności. Niniejsze informacje dotyczące dostępności dotyczą następujących stron internetowych i aplikacji mobilnych oraz usług e-commerce, które świadczymy za ich pośrednictwem:", "services": [{"name": "a) eshop.skoda-auto.cz", "description": "Jest to usługa e-commerce, która polega na prowadzeniu sklepu internetowego, który umożliwia użytkownikom wyszukiwanie, przeglądanie, wybieranie i kupowanie towarów online (Škoda Lifestyle i Oryginalne akcesoria). Usługa obejmuje takie funkcje, jak: katalog produktów (w tym filtrowanie i wyszukiwanie), szczegółowy widok poszczególnych pozycji, dodawanie towarów do koszyka, zawieranie umowy zakupu online (mechanizm click-wrap — użytkownik zawiera umowę, aktywnie klikając przycisk, taki jak „Zamów” po zapoznaniu się z regulaminem), płatność online, komunikacja z obsługą klienta. Usługa jest dostępna za pośrednictwem interfejsu internetowego pod powyższym adresem i jest zoptymalizowana do użytku na komputerach i urządzeniach mobilnych. Nie używamy żadnego specjalistycznego sprzętu, który byłby niezbędny do uzyskania dostępu do tej usługi. Użytkownicy mogą korzystać z własnego urządzenia (np. komputera, telefonu komórkowego lub tabletu), aby uzyskać dostęp do usługi. Nasz cyfrowy interfejs jest zaprojektowany tak, aby był interoperacyjny ze standardowymi technologiami wspomagającymi."}, {"name": "b) Škoda ID", "description": "Škoda ID to cyfrowe konto użytkownika, które umożliwia poszczególnym użytkownikom dostęp do naszych usług online. Usługa zapewnia scentralizowane logowanie do cyfrowych funkcji pojazdu oraz do aplikacji internetowej i mobilnej MyŠkoda. Korzystając z Škoda ID, użytkownicy mogą zarządzać swoim osobistym profilem, łączyć swoje konto z konkretnym pojazdem, aktywować i używać wybranych funkcji pojazdu online, uzyskiwać dostęp do zdalnego sterowania pojazdem (np. klimatyzacji, blokowania), monitorować informacje o stanie pojazdu i statystyki jazdy oraz zarządzać subskrypcjami usług. Usługa jest świadczona za pośrednictwem interfejsu internetowego i aplikacji mobilnej. Nie używamy żadnego specjalistycznego sprzętu, który byłby niezbędny do uzyskania dostępu do tej usługi. Użytkownicy mogą korzystać z własnego urządzenia (np. komputera, telefonu komórkowego lub tabletu), aby uzyskać dostęp do usługi. Nasz cyfrowy interfejs jest zaprojektowany tak, aby był interoperacyjny ze standardowymi technologiami wspomagającymi."}, {"name": "c) Škoda Connect", "description": "Škoda Connect to zestaw usług online, który łączy Twój pojazd Škoda z internetem i smartfonem, oferując zwiększoną wygodę, bezpieczeństwo i informacje rozrywkowe. Oferuje funkcje takie jak aktualizacje ruchu drogowego w czasie rzeczywistym, zdalny dostęp do pojazdu (np. blokowanie/odblokowywanie, pozycja parkingowa), pomoc w nagłych wypadkach i proaktywne przypomnienia o serwisie. Usługa jest świadczona za pośrednictwem interfejsu internetowego, aplikacji mobilnej i pokładowego systemu informacyjno-rozrywkowego. Podczas korzystania z dostarczanych przez nas urządzeń upewniamy się, że ich fizyczne elementy sterujące i interfejsy oprogramowania są zgodne z wymogami dostępności i są kompatybilne z technologiami wspomagającymi."}, {"name": "d) Aplikacja mobilna MyŠkoda, Škoda Media Room", "description": "MyŠkoda to usługa cyfrowa i aplikacja mobilna, która umożliwia użytkownikom dostęp do informacji o pojeździe i zdalne sterowanie nim. Za pośrednictwem usługi użytkownicy mogą monitorować stan techniczny pojazdu, planować trasy, zarządzać ładowaniem (w przypadku samochodu elektrycznego), korzystać z usług sieciowych (np. Powerpass) i personalizować ustawienia pojazdu. Škoda Media Room to mobilna aplikacja informacyjna zaprojektowana specjalnie dla dziennikarzy, mediów i ogółu społeczeństwa zainteresowanego tym, co dzieje się wokół naszej marki. Zapewnia dostęp do aktualnych komunikatów prasowych, materiałów multimedialnych, podcastów i innych oficjalnych informacji o naszych produktach, innowacjach, wynikach i działaniach."}]}, {"title": "B. ZGODNOŚĆ Z WYMOGAMI DOSTĘPNOŚCI", "content": "Strony internetowe, w tym powiązane aplikacje online i usługi świadczone na urządzeniach mobilnych, w tym aplikacje mobilne, funkcje identyfikacyjne i metody identyfikacji oraz podpisy elektroniczne, są postrzegalne, funkcjonalne, zrozumiałe i stabilne. Wymagania dotyczące dostępności są zgodne ze zharmonizowaną normą EN 301 549 i normą WCAG 2.1. Aby uzyskać optymalne wyświetlanie i wydajność, należy korzystać z następujących przeglądarek internetowych:", "disclaimer": "Strona internetowa i aplikacje mobilne nie są dostępne w rozumieniu prawa, w przypadku gdy nie świadczymy usług handlu elektronicznego, tj. w tych częściach strony internetowej i aplikacji mobilnych, które nie są częścią procesu zawierania umowy na odległość z konsumentem (na przykład czysto informacyjne części strony internetowej i aplikacji mobilnych). Jednak nawet w tych częściach strony internetowej i aplikacji mobilnych staramy się, aby były one dostępne dla jak najszerszego grona naszych klientów.", "requirements": {"mobile_apps": ["Chrome dla Androida", "Safari dla iPhone''a"], "web_browsers": ["Chrome 116.0 i nowsze", "Safari 16.0 i nowsze", "Edge 116 i nowsze", "Firefox 116 i nowsze"], "operating_systems": ["Windows: 10 i nowsze", "Mac OS: Catalina i nowsze", "iOS: 16.1 i nowsze", "Android: 9.0 i nowsze"]}}, {"title": "C. USŁUGI WSPARCIA", "contact": {"email": "infoline@skoda-auto.cz", "infolinia": "+420 236 090 002"}, "content": "Nasze usługi wsparcia udzielają informacji o dostępności usług i ich zgodności z technologiami wspomagającymi. Osoby niepełnosprawne mogą również korzystać z następujących usług wsparcia:"}, {"title": "D. FORMAT AUDIO", "content": "Informacje o dostępności udostępniamy również w formacie audio. Wersja audio informacji o dostępności jest dostępna za pośrednictwem naszej infolinii."}, {"title": "E. SKUTECZNOŚĆ", "content": "Informacje te obowiązują od 28. 6. 2025 r."}]}]}}, "offer_number": null, "mapped_ai_data": {"fuel": "Benzyna mHEV (PB-mHEV)", "brand": "SKODA", "model": "Octavia Combi", "trim_level": "Essence", "engine_class": "mhev", "transmission": "Automatyczna", "vehicle_type": "Osobowy", "samar_category": "Podstawowa - C NIŻSZA ŚREDNIA", "samar_candidates": [{"klasa": "Podstawowa - C NIŻSZA ŚREDNIA", "confidence": 1.0}], "engine_candidates": [{"klasa": "Benzyna mHEV (PB-mHEV)", "confidence": 1.0}, {"klasa": "Hybryda (HEV)", "confidence": 0.1}, {"klasa": "Benzyna (PB)", "confidence": 0.05}]}, "configuration_code": "CPB96GQH", "_extraction_metadata": {"model": "gemini-2.5-pro", "stage": "digital_twin", "output_tokens": 6526, "prompt_tokens": 2831, "thinking_tokens": 9690}, "_evaluation_reasoning": "Wariant A jest znacznie bardziej kompletny i szczegółowy, obejmując szeroki zakres danych, w tym pełne informacje o wyposażeniu standardowym, opcjonalnym, etykietach opon i sekcjach prawnych, co lepiej odpowiada koncepcji ''cyfrowego bliźniaka''. Oba warianty poprawnie odczytały kwoty, bez błędów rozdzielania cen."}'::jsonb, '37d49eee93c892a5343a4b482f0b8615', NULL, '2026-03-10T18:16:34.704631+00:00', FALSE, 'Osobowy', '2026-03-10T18:19:49.794297+00:00', NULL);
