INSERT INTO "public"."vehicle_synthesis" ("id", "brand", "model", "offer_number", "raw_pdf_url", "schema_version", "verification_status", "synthesis_data", "file_hash", "notes", "created_at", "zabudowa_apr_wr", "document_category", "processing_updated_at", "document_markdown") VALUES ('ba545abd-2bbe-4725-a203-e5f28cd4bf46', 'Volkswagen', 'Arteon', 'GOV-22-116290', 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/ba545abd-2bbe-4725-a203-e5f28cd4bf46-SIEMENS_ARTEON_12.05.2022.pdf', NULL, 'completed', '{"brand": "Volkswagen", "model": "Arteon", "card_summary": {"fuel": "Benzyna", "wheels": "19", "power_hp": 190, "emissions": "7,3 l/100 km, 166 g/km CO2", "base_price": "186 890 PLN brutto", "body_style": "Liftback", "drive_type": "Napęd FWD", "powertrain": "2.0 TSI 190 KM", "trim_level": "R-Line", "_validation": {"summary": {"details": "Ceny bazowe wyglądają poprawnie, ale występują drobne niezgodności.", "verdict": "Wykryto 1 ostrzeżeń", "confidence": "MEDIUM", "suggestions": ["Zweryfikuj opcje z brakującymi cenami"]}, "is_valid": true, "warnings": [{"rule": "AUTO_FIX_APPLIED", "message": "Automatycznie wyliczono brakujące options_price jako 1906 aby zbilansować sumę.", "severity": "INFO"}], "parsed_prices": {"base": 186890.0, "total": 188796.0, "options": 1906.0}}, "power_range": "MID (131 - 200 KM)", "total_price": "188 796 PLN brutto", "has_tow_hook": true, "paid_options": [{"name": "Obręcze aluminiowe Montevideo 8J x 19, z czarnym połyskiem", "price": "2 530 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Listwy dekoracyjne aluminiowe Black Carbon na desce rozdzielczej i drzwiach", "price": "480 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Sportowa kierownica 3-ramienna, multifunkcyjna, obszyta skórą, podgrzewana,z łopatkami do zmiany biegów", "price": "750 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Elektrycznie regulowane podparcia lędźwi z funkcją masażu w fotelu kierowcy, manualnie regulowane w fotelu pasażera", "price": "910 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Szyba tylna i boczne tylne przyciemniane, przednie boczne dźwiękoszcz., dodatkowe wytłumienie wnętrza", "price": "1 570 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Przednia szyba podgrzewana bezprzewodowo i odbijająca promienie podczerwone", "price": "1 850 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "System Keyless Access - bezkluczykowy dostęp i uruchamianie pojazdu", "price": "2 320 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Design Plus", "price": "4 270 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Hak holowniczy składany, elektrycznie odblokowywany", "price": "4 440 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Safety Plus z Emergancy Assist", "price": "6 390 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Active Lighting System - Reflektory LED z Dynamic Light Assist", "price": "6 540 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Koło zapasowe, dojazdowe", "price": "590 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Automatyczna DSG", "_price_domain": "brutto", "options_price": "1906 PLN brutto", "vehicle_class": "Osobowy", "exterior_color": "Szary \"Mondstein\" (Bez dopłaty)", "engine_capacity": "2.0", "engine_category": "Benzyna (PB)", "is_metalic_paint": true, "service_equipment": null, "engine_designation": "TSI", "standard_equipment": ["Ubezpieczenie opon - 36 miesięcy", "Śruby kół z zabezpieczeniem antykradzieżowym", "Tapicerka siedzeń R-Line - środkowa część foteli z mikrofibry Art Velours, boki pokryte skórą Vienna", "Fotel kierowcy ergoComfort z elektryczną regulacją odcinka lędźwiowego i kąta nachylenia oparcia", "Fotel kierowcy i pasażera Top Comfort", "Oparcie tylnej kanapy (60/40) i składane, z podłokietnikiem, miejscem na napoje, otworem do długich przedmiotów", "Podgrzewane siedzenia przednie", "Podłokietnik z przodu ze schowkiem oraz dwoma nawiewami powietrza dla pasażerów z tyłu", "Tapicerka drzwi i panelu bocznego", "8 głośników", "App Connect - połączenie smartfona z sam smartfona z samochodem [w tym bezprzewodowe dla CarPlay, Android Auto]", "Digital Cockpit Pro - Cyfrowy zestaw wskaźników z komputerem pokładowym o przekątnej 10,25\", personalizowany", "Dwa gniazda USB-C w konsoli środkowej", "Instalacja telefoniczna (Bluetooth)", "Progresywne wspomaganie układu kierowniczego", "Przygotowanie do We Connect Plus (na 3 lata), zawiera We Connect2", "Radio", "Tuner cyfrowy DAB+", "Czujnik zmierzchu - automatyczne włączenie świateł z funkcją Coming / Leaving Home", "Hamulce tarczowe z tyłu", "Listwy ozdobne dookoła szyb bocznych, chromowane", "Lusterka zew. składane elektrycznie, podgrzewane, ośw. przestrzeni pod lust. automat. obniżenie lusterka pasażera", "Nakładki na progi ze stali nierdzewnej", "Tylne światła w technologii 3D LED z dynamicznymi kierunkowskazami", "Czarna podsufitka", "Dywaniki materiałowe z przodu i z tyłu", "Gałka dźwigni zmiany biegów obszyta skórą", "Konsola środkowa ze wstawkami Piano Black", "Nakładki na pedały, aluminiowe", "Oświetlenie Ambiente w 30 kolorach do wyboru", "Oświetlenie przestrzeni wokół nóg", "Składana podłoga bagażnika", "Zbiornik paliwa o pojemności 66 litrów", "Aktywny tempomat z automatyczną regulacją odległości ACC oraz funkcją \"stop & go\" (do 210 km/h)\"", "Czujnik deszczu", "Czujnik systemów asystujących", "Gniazdo 12 V w konsoli środkowej", "Gniazdo 12 V w środkowej konsoli, z tyłu", "Klimatyzacja automatyczna Air Care Climatronic, trzystrefowa z filtrem antyalergicznym", "Lusterko wsteczne, automatycznie przyciemniane", "Ogrzewane dysze spryskiwaczy przedniej szyby", "System Start-Stop z odzyskiwaniem energii przy hamowaniu", "Elektromechaniczny hamulec postojowy z funkcją Auto Hold", "Emergency call - automatyczne wzywanie pomocy", "ESP, ASR, ABS, MSR, wraz z asystentem siły hamowania i stabilizacją toru jazdy przyczepy", "Isofix - przygotowanie do montażu 2 fotelików na zewnętrznych siedziskach tylnej kanapy, zgodnie z normą I-Size", "Poduszka powietrzna kierowcy i pasażera, dla pasażera z funkcją dezaktywacji, poduszka kolanowa kierowcy", "Sygnalizacja zmęczenia kierowcy", "System Front Assist z funkcją awaryjnego hamowania", "System Lane Assist, System Traffic Jam Assist, System Emergency Assist", "System wykrywający pieszych i aktywna pokrywa silnika"], "financial_reasoning": "Zidentyfikowano następujące kwoty w dokumencie: ''Cena modelu (brutto)'': 186 890 zł, ''Wartość wyposażenia dodatkowego (brutto)'': 32 640 zł, ''Cena katalogowa konfiguracji (brutto)'': 219 530 zł, ''Rabat flotowy'': 30 734 zł, ''Cena samochodu z uwzględnieniem rabatu flotowego (brutto)'': 188 796 zł, ''Cena całkowita samochodu (brutto)'': 188 796 zł, ''netto'': 153 493 zł.  \n\nRelacje matematyczne:\n1. Cena modelu (brutto) (186 890 zł) + Wartość wyposażenia dodatkowego (brutto) (32 640 zł) = Cena katalogowa konfiguracji (brutto) (219 530 zł). Ta relacja jest zgodna.\n2. Cena katalogowa konfiguracji (brutto) (219 530 zł) - Rabat flotowy (30 734 zł) = Cena samochodu z uwzględnieniem rabatu flotowego (brutto) (188 796 zł). Ta relacja jest zgodna.\n3. Cena samochodu z uwzględnieniem rabatu flotowego (brutto) (188 796 zł) jest równa Cenie całkowitej samochodu (brutto) (188 796 zł). Ta relacja jest zgodna.\n4. Sprawdzenie VAT: Cena netto (153 493 zł) * 1.23 = 188 796.39 zł, co jest zgodne z ceną brutto (188 796 zł) z dokładnością do zaokrągleń.\n\nNa podstawie powyższej analizy:\n- Cena bazowa (przed opcjami i rabatami) to ''Cena modelu (brutto)''.\n- Cena opcji to ''Wartość wyposażenia dodatkowego (brutto)''.\n- Cena całkowita (po rabatach) to ''Cena całkowita samochodu (brutto)''.\n\nDomena cenowa to ''brutto'', co jest wielokrotnie potwierdzone w dokumencie.", "suggested_discount_pct": 14.0, "is_current_year_vehicle": true, "suggested_discount_source": "Rabat flotowy", "suggested_discount_confidence": 0}, "digital_twin": {"pages": [{"content": [{"type": "header", "content": [{"type": "logo", "brand": "Volkswagen"}]}, {"type": "image", "description": "Widok z przodu, z lewego boku na szarego Volkswagena Arteon. Samochód stoi na białym tle. Na tablicy rejestracyjnej widnieje napis ''Arteon''."}, {"type": "text_block", "content": "Poznaj najlepsze rozwiązania Volkswagena dla Twojego biznesu."}, {"type": "metadata_block", "content": ["Data przygotowania: 2022-05-12", "Data obowiązywania: 2022-05-14", "Informacja handlowa nr: GOV-22-116290"]}, {"type": "footer", "content": "Zdjęcie poglądowe"}], "page_number": 1}, {"content": [{"type": "header", "content": [{"text": "Informacja handlowa dla firmy", "type": "title"}, {"type": "logo", "brand": "Volkswagen"}]}, {"type": "configuration_summary", "title": "Twoja konfiguracja: Arteon R-Line", "specifications": [{"name": "Lakier", "type": "visual_specification", "value": "Szary \"Mondstein\"", "image_description": "Kwadratowa próbka szarego koloru."}, {"name": "Wnętrze", "type": "visual_specification", "value": "Czarne R-Line/Czarna/Czarna", "image_description": "Zdjęcie fragmentu czarnego fotela z teksturą."}, {"name": "Felgi", "type": "visual_specification", "value": "Obręcze aluminiowe Montevideo 8J x 19, z czarnym połyskiem", "image_description": "Zdjęcie aluminiowej felgi o skomplikowanym, wieloramiennym wzorze w kolorze srebrnym z czarnymi akcentami."}], "technical_data": [{"name": "Silnik", "value": "2.0 TSI 140 kW 190 KM / 3H84LZ"}, {"name": "Skrzynia biegów", "value": "automatyczna, DSG, 7-stopniowa"}, {"name": "Zużycie paliwa¹", "value": "7,3 l/100 km"}, {"name": "Średni poziom Emisji CO2 ¹", "value": "166 g/km"}], "image_description": "Widok z przodu, z lewego boku na szarego Volkswagena Arteon, identyczny jak na stronie 1."}, {"type": 