INSERT INTO "public"."vehicle_synthesis" ("id", "brand", "model", "offer_number", "raw_pdf_url", "schema_version", "verification_status", "synthesis_data", "file_hash", "notes", "created_at", "zabudowa_apr_wr", "document_category", "processing_updated_at", "document_markdown") VALUES ('bd5e546f-9d90-428e-b144-dd9588fd02f1', 'SKODA', 'Octavia Combi', NULL, 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/bd5e546f-9d90-428e-b144-dd9588fd02f1-car-card-CQZXRDQL.pdf', NULL, 'completed', '{"brand": "SKODA", "model": "Octavia Combi", "card_summary": {"fuel": "Diesel", "wheels": "17", "power_hp": 150, "emissions": "Emisja CO2 w cyklu mieszanym 121 g/km / Zużycie paliwa/energii w cyklu mieszanym 4,6 l/100km", "base_price": "166 550 PLN brutto", "body_style": "Kombi", "drive_type": "Napęd FWD", "powertrain": "2.0 TDI 150 KM", "trim_level": "Drive Selection", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": 166550.0, "total": 179400.0, "options": 12850.0}}, "power_range": "MID (131 - 200 KM)", "total_price": "179 400 PLN brutto", "has_tow_hook": null, "paid_options": [{"name": "Szary Steel Niemetalizowany", "price": "2650 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Design Selection Lodge", "price": "1900 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Winter Plus", "price": "1200 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Infotainment Plus", "price": "5100 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Skórzana podgrzewana kierownica wielofunkcyjna z manetkami", "price": "600 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Assisted Drive", "price": "700 PLN brutto", "cat