INSERT INTO "public"."vehicle_synthesis" ("id", "brand", "model", "offer_number", "raw_pdf_url", "schema_version", "verification_status", "synthesis_data", "file_hash", "notes", "created_at", "zabudowa_apr_wr", "document_category", "processing_updated_at", "document_markdown") VALUES ('f63bd9db-aadb-4294-822a-6b69834b5a36', 'Audi', 'A7 Sportback 45 TFSI quattro 195 kW (265 KM) S tronic', 'GOA-24-167193', 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/f63bd9db-aadb-4294-822a-6b69834b5a36-oferta_goa-24-167193-6b8f04.pdf', NULL, 'completed', '{"brand": "Audi", "model": "A7 Sportback 45 TFSI quattro 195 kW (265 KM) S tronic", "card_summary": {"suggested_discount_pct": 24.0, "suggested_discount_source": "Dopasowano markę Audi oraz model A7 Sportback z kodem 4KA***, który pasuje do kodu modelu pojazdu 4KA03Y. Wykluczenia nie mają zastosowania.", "suggested_discount_confidence": 98}, "digital_twin": {"technical_data": {"mass": {"title": "Masa", "unladen_weight": "1.835 kg", "unbraked_trailer": "750 kg", "gross_vehicle_weight": "2.385 kg", "roof_load_hitch_load": "100/95 kg", "braked_trailer_12_percent": "2000 kg"}, "title": "Dane techniczne", "capacity": {"title": "Pojemność", "fuel_tank": "ok. 73 l", "luggage_compartment": "535/1390 l"}, "wltp_data": {"title": "Dane WLTP*", "disclaimer": "Od dnia 1 września 2018 r. WLTP w pełni zastąpił nowy europejski cykl jezdny (NEDC), który stanowił dotychczasową procedurę badania zużycia paliwa i emisji CO2. Ze względu na bardziej realistyczne warunki badania wartości zużycia paliwa i emisji CO2 mierzone na podstawie WLTP są w wielu przypadkach w liczbach bezwzględnych wyższe od wartości mierzonych na podstawie NEDC.", "co2_emissions": {"low_cycle": "253 g/km", "high_cycle": "153 g/km", "medium_cycle": "184 g/km", "combined_cycle": "180 g/km", "extra_high_cycle": "173 g/km"}, "fuel_consumption": {"low_cycle": "11.1 l/100km", "high_cycle": "6.7 l/100km", "medium_cycle": "8.1 l/100km", "combined_cycle": "7.9 l/100km", "extra_high_cycle": "7.6 l/100km"}}, "suspension": {"tires": "Opony 245/45 R19. 3-letnie ubezpieczenie opon w cenie.", "title": "Zawieszenie", "wheels": "Obręcze kół ze stopu metali lekkich 8.5Jx19\", 10 - ramienne, stylistyka Y, grafitowoszare, z oponami 245/45 R19. 3-letenie ubezpieczenie opon w cenie.", "rear_axle": "5-wahaczowa oś tylna; stabilizator rurowy", "front_axle": "5-wahaczowa oś przednia; stabilizator rurowy"}, "performance": {"title": "Osiągi", "max_speed": "250 km/h", "acceleration_0_100": "6,2 s"}, "engine_and_emissions": {"title": "Osiągi", "max_torque": "370/1600 - 4500 Nm przy obr.", "max_power_kw": "195 kW przy 5.250 - 6.500 obr./min", "engine_capacity": "1984 cm3", "emission_control": "Katalizator, sonda lambda, filtr cząstek stałych GPF"}}, "document_footer": {"email": "mateusz.brzytwa@cichy-zasada.pl", "phone": "785 557 727", "dealership": "Grupa Cichy - Zasada Oddział Volkswagen Centrum Szczecin", "legal_text": "Podane ceny obejmują podatek VAT (23%) i nie stanowią oferty w rozumienia art. 66 §1, kodeksu cywilnego. Zawartość domówionego pakietu lub opcji może zmienić elementy wyposażenia standardowego - w niektórych przypadkach bezzwrotnie zastępując elementy wyposażenia standardowego. Zamieszczone informacje, w tym prezentowane grafiki mają wyłącznie charakter poglądowy.", "model_year": "2024", "offer_number": "GOA-24-167193", "sales_person": "Mateusz Brzytwa", "creation_date": "2024-05-15", "validity_date": "2024-05-19", "page_numbering": "1/12", "production_year": null}, "document_header": {"logo": "Audi logo", "customer_information": {"phone": "914626202", "title": "Informacje handlowe przygotowane dla:", "address": "Pomorska 42\n70-812 Szczecin", "company_name": "FairWind Poland Sp. z o. o", "customer_name": "Łukasz Sotek"}}, "vehicle_summary": {"color": "czarny Briliant", "title": "Audi A7 Sportback 45 TFSI quattro 195 kW (265 KM) S tronic", "interior": "czarne-czarne-szew szary Rock/czarna-czarna/czarna/srebrna Moon", "quantity": 1, "model_code": "4KA03Y", "offer_number": "GOA-24-167193", "configuration_id": "AXCTCFBQ"}, "visual_elements": [{"type": "image", "description": "Widok zewnętrzny czarnego Audi A7 Sportback z przodu, z lewej strony."}, {"type": "image", "description": "Widok wnętrza pojazdu, deska rozdzielcza, konsola środkowa i przednie fotele."}], "service_packages": {"audi_extensive": {"title": "Audi Extensive", "content": "Audi Extensive jest to pakiet naprawczy umożliwiający nieodpłatne usunięcie usterek w samochodzie po upływie gwarancji, ale na tych samych warunkach.\nZasady korzystania z Audi Extensive są proste i przejrzyste, a pakiet może zostać zakupiony do każdego nowego samochodu Audi. Zachęcamy do zakupu pakietu naprawczego Audi Extensive w trakcie konfigurowania nowego Audi, aby cieszyć się pełną ochroną przed nieprzewidzianymi kosztami napraw.\nMogą Państwo wybrać jeden z dwóch wariantów pakietów. Pakiet naprawczy Audi Extensive dobiega końca po upływie ustalonego pakietem okresu lub po przekroczeniu maksymalnego przebiegu - w zależności od tego, które ze zdarzeń nastąpi jako pierwsze", "benefits": {"title": "Przegląd korzyści:", "points": ["możliwość wyboru między dwoma wariantami pakietu, zależnie od preferencji Użytkownika Audi", "dostępność dla wszystkich modeli oraz wersji silnikowych", "efektywna ochrona przed kosztami nieprzewidzianych napraw,", "utrzymanie samochodu w doskonałym stanie dzięki obsłudze serwisowej zgodnej z wytycznymi Producenta"]}, "contact_note": "Szczegółowe zasady i warunki znajdują się w Certyfikacie Pakietu naprawczego Audi Extensive. Zachęcamy do kontaktu ze Sprzedawcą", "options_table": {"rows": [{"Czas trwania*": "Do końca czwartego roku eksploatacji", "Maksymalny przebieg (km)*": "120 000"}, {"Czas trwania*": "Do końca piątego roku eksploatacji", "Maksymalny przebieg (km)*": "150 000"}], "headers": ["Czas trwania*", "Maksymalny przebieg (km)*"], "footnote": "* w zależności od tego, co nastąpiło pierwsze"}}, "service_reviews": {"title": "Pakiety Przeglądów Serwisowych Audi", "content": "Niezawodność w każdej sytuacji wynika z doskonałego stanu technicznego auta. Jednak aby to osiągnąć, Twoje Audi wymaga stałej opieki serwisowej. Dzięki ofercie serwisowej Audi nie musisz już martwić się przeglądami.\nW odpowiedzi na potrzeby naszych Klientów stworzyliśmy kompleksowy Pakiet Przeglądów Serwisowych Audi, w ramach którego najlepsi Specjaliści zadbają o wygodny i profesjonalny przegląd Twojego Audi. To komfort i jakość w pakiecie!\nPakiet Przeglądów Serwisowych Audi pozwala cieszyć się profesjonalnymi przeglądami serwisowymi Audi wraz z materiałami eksploatacyjnymi, które zgodnie z planem serwisowym Twojego Audi obejmuje pakiet.\nPakiet Przeglądów Serwisowych Audi Plus to doskonałe rozwinięcie Pakietu Przeglądów Serwisowych. W jego ramach zyskujesz dodatkowe możliwości serwisowe z wykorzystaniem oryginalnych materiałów eksploatacyjnych i części. Dzięki temu Twoje Audi jest jeszcze lepiej przygotowane do każdej podróży.\nPrzedstawiciele najbliższego Salonu Audi z przyjemnością opowiedzą o szczegółach oferty i pomogą wybrać odpowiedni wariant pakietu.", "advantages": {"title": "Pakiety Przeglądów Serwisowych Audi mają wiele zalet:", "points": ["Wygoda. Obsługa ekspertów u 36 Partnerów Serwisowych Audi w całej Polsce.", "Pewność i spokój. Gwarancja przewidywalnych kosztów bez martwienia się o ewentualne zmiany cen części, materiałów eksploatacyjnych i obsługi.", "Elastyczność. Możliwość wyboru odpowiedniego wariantu pakietu: czasu trwania i limitu kilometrów.", "Profesjonalizm. Najlepsi specjaliści i Oryginalne Części Audi.", "Przejrzystość i transparentność. Jasne warunki obsługi i czytelny zakres ochrony bez dodatkowych skomplikowanych procedur.", "Wyższa wartość pojazdu. Regularnie przeprowadzane i udokumentowane przeglądy dają gwarancję wyższej wartości Audi przy ewentualnej odsprzedaży w przyszłości."]}, "availability_note": "Szczegółowe informacje o zakresie wybranych wariantów pakietów i o warunkach przystąpienia do programu są dostępne u Dealerów i Partnerów Serwisowych Audi."}}, "tire_information": {"title": "Informacje dotyczące opon", "labels": [{"size": "275/35ZR21 (103Y) XL", "class": "C1", "model": "PZERO AO", "ice_tire": "Nie", "wet_grip": "A", "snow_tire": "Nie", "identifier": "28571", "manufacturer": "Pirelli", "noise_level_db": "70 dB(A)", "production_end": null, "fuel_efficiency": "C", "production_start": "2019-W16", "noise_level_class": "A"}, {"size": "245/45R19 102 Y XL", "class": "C1", "model": "PILOT SPORT 4 ACOUSTIC AO", "ice_tire": "Nie", "wet_grip": "A", "snow_tire": "Nie", "identifier": "559812", "manufacturer": "Michelin", "noise_level_db": "71 dB(A)", "production_end": null, "fuel_efficiency": "B", "production_start": "2000-W01", "noise_level_class": "B"}, {"size": "245/45R19 102 Y XL", "class": "C1", "model": "PZERO", "ice_tire": "Nie", "wet_grip": "A", "snow_tire": "Nie", "identifier": "39741", "manufacturer": "Pirelli", "noise_level_db": "69 dB(A)", "production_end": null, "fuel_efficiency": "B", "production_start": "2020-W25", "noise_level_class": "A"}, {"size": "245/45 R19 102 Y XL", "class": "C1", "model": "Turanza T005", "ice_tire": "Nie", "wet_grip": "A", "snow_tire": "Nie", "identifier": "9386", "manufacturer": "BRIDGESTONE", "noise_level_db": "70 dB(A)", "production_end": null, "fuel_efficiency": "B", "production_start": "2018-W36", "noise_level_class": "B"}, {"size": "275/35ZR21 (103Y) XL", "class": "C1", "model": "ventus S1 evo3 (K127)", "ice_tire": "Nie", "wet_grip": "A", "snow_tire": "Nie", "identifier": "1026274", "manufacturer": "Hankook", "noise_level_db": "73 dB(A)", "production_end": null, "fuel_efficiency": "C", "production_start": "2019-W41", "noise_level_class": "B"}, {"size": "275/35 ZR 21 (103Y) XL", "class": "C1", "model": "SportContact 6 AO", "ice_tire": "Nie", "wet_grip": "A", "snow_tire": "Nie", "identifier": "311530", "manufacturer": "Continental", "noise_level_db": "73 dB(A)", "production_end": null, "fuel_efficiency": "C", "production_start": "2020-W47", "noise_level_class": "B"}, {"size": "245/45 R 19 102 Y XL", "class": "C1", "model": "PremiumContact 6", "ice_tire": "Nie", "wet_grip": "A", "snow_tire": "Nie", "identifier": "357455", "manufacturer": "Continental", "noise_level_db": "72 dB(A)", "production_end": null, "fuel_efficiency": "B", "production_start": "2018-W44", "noise_level_class": "B"}], "introduction": "Zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2020/740 z dnia 25 maja 2020 r. w sprawie etykietowania opon pod kątem efektywności paliwowej i innych parametrów, zmieniające rozporządzenie (UE) 2017/1369 oraz uchylające rozporządzenie (WE) nr 1222/2009 - poniżej znajduje się lista etykiet opon wraz z kartami informacyjnymi produktu, która przedstawia opony, jakie potencjalnie mogą być zamontowane w Twoim samochodzie. Ze względów logistycznych i produkcyjnych nie ma możliwości wyboru danej opony od konkretnego producenta opon. Więcej informacji na temat opon można uzyskać u autoryzowanego Dealera Marki AUDI oraz pod adresem: https://www.audi.pl/pl/web/pl/modele/etykieta-opon.html"}, "financial_summary": {"leasing_offer": {"title": "Rata miesięczna netto Audi Perfect Lease dla przedsiębiorców", "mileage_limit": "30 000 km/rok", "financing_period": "24 m-cy", "monthly_rate_net": "5 028 PLN", "initial_payment_net_amount": "17 616 PLN", "initial_payment_net_percentage": "5%"}, "price_calculation": {"title": "CENA MODELU", "discount": "95 339 PLN / 22,00 %", "base_price": "294 400 PLN", "catalog_price": "433 360 PLN", "price_with_vat": "338 021 PLN", "accessories_price": "0 PLN", "final_price_with_vat": "338 021 PLN", "additional_equipment_price": "138 960 PLN", "audi_extensive_package_price": "0 PLN", "packages_excluded_from_discount_price": "0 PLN"}}, "customer_statement": {"title": "Oświadczenie", "content": "Szanowna/y Pani/Panie,\n\nw celu spełnienia norm emisji spalin stawianych przez prawo europejskie, branża motoryzacyjna musi podjąć odpowiednie kroki polegające na dostosowaniu oferty do nowych wymagań. Audi nie pozostaje w tyle. Dokładamy wszelkich starań, aby produkowane przez nas samochody były bezpieczne oraz spełniały wszelkie normy emisyjne stawiane przez Unię Europejską.\n\nTym samym pragniemy Panią/Pana uprzedzić, że istnieje możliwość, iż dane dotyczące zużycia paliwa i emisji CO₂ obliczone dla Pani/Pana pojazdu będą różnić się od danych dla pojazdu, który Pani/Pan zamówił/a, co uzależnione jest od terminu rozpoczęcia produkcji samochodu objętego ofertą. Audi dokłada wszelkich starań, aby dane dotyczące zużycia paliwa i emisji CO2 zawsze były jak najbardziej aktualne, jednak ze względu na to, że dane te są zależne od wariantu, wersji, a także użytych w procesie produkcji komponentów i elementów wyposażenia, narażone są na rozbieżności.\n\nW przypadku, gdy dane dotyczące zużycia paliwa i emisji CO2 będą różnić się od zamówionych, niezwłocznie poinformujemy Panią/Pana o nowych danych technicznych samochodu.\n\nW przypadku złożenia zamówienia prosimy o potwierdzenie zapoznania się z powyższymi informacjami.\n\nNiniejszym potwierdzam, że należycie zapoznałem/-am się z powyższymi informacjami.", "signature_field": "[Data i podpis klienta]"}, "standard_equipment": {"items": [{"code": "9AK", "name": "2-strefowa komfortowa klimatyzacja automatyczna", "note": "zastąpione przez 4-strefowa komfortowa klimatyzacja automatyczna"}, {"code": "8RM", "name": "8 głośników", "note": "zastąpione przez Bang & Olufsen Premium Sound System z dźwiękiem 3D"}, {"code": "5MA", "name": "Aplikacje dekoracyjne - lakier grafitowoszary", "note": "zastąpione przez Aplikacje dekoracyjne z ciemnego szczotkowanego, matowego aluminium"}, {"code": "1T3", "name": "Apteczka z trójkątem ostrzegawczym i kamizelkami odblaskowymi"}, {"code": "8G1", "name": "Asystent świateł drogowych", "note": "zastąpione przez Reflektory HD Matrix LED z Audi laser light, z przyciemnionymi elementami we wnętrzu, światła tylne LED i 