INSERT INTO "public"."vehicle_synthesis" ("id", "brand", "model", "offer_number", "raw_pdf_url", "schema_version", "verification_status", "synthesis_data", "file_hash", "notes", "created_at", "zabudowa_apr_wr", "document_category", "processing_updated_at", "document_markdown") VALUES ('fc684ec2-acf2-4797-bdf5-4c2497a31892', 'Opel', 'Astra Sports Tourer', NULL, 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/fc684ec2-acf2-4797-bdf5-4c2497a31892-FoodCare%20-%20Opel%20Astra%20VI%20GS%20Kombi%20Diesel%20Automat8.pdf', NULL, 'completed', '{"brand": "Opel", "model": "Astra Sports Tourer", "card_summary": {"fuel": "Diesel", "wheels": "17", "power_hp": 130, "emissions": "Brak", "base_price": "154 450,00 PLN brutto", "body_style": "Kombi", "drive_type": "Napęd FWD", "powertrain": "1.5 R4 130KM Automat 8 biegowy", "trim_level": "GS", "_validation": {"summary": {"details": "Cena bazowa jest wyższa od łącznej. Po zamianie pól arytmetyka się zgadza.", "verdict": "Prawdopodobna zamiana pól base↔total", "confidence": "LOW", "suggestions": ["Zamień wartości base_price i total_price"]}, "is_valid": false, "warnings": [{"rule": "BASE_PLUS_OPTIONS_VS_TOTAL", "actual": 108166.0, "message": "baza(154450) + opcje(13100) = 167550, ale total = 108166 (Δ 59384 / 35.4%)", "diff_pct": 35.44, "expected": 167550.0, "severity": "ERROR"}, {"rule": "BASE_TOTAL_SWAPPED", "actual": 154450.0, "message": "base(154450) > total(108166) — kolejność cen może być odwrócona", "expected": 108166.0, "severity": "WARNING"}], "parsed_prices": {"base": 154450.0, "total": 108166.0, "options": 13100.0}}, "power_range": "LOW (do 130 KM)", "total_price": "108 166,00 PLN brutto", "has_tow_hook": null, "paid_options": [{"name": "Lakier metalizowany - czarny metalizowany", "price": "3 200,00 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}, {"name": "Pakiet Techniczny (Radio z nawigacją, Układ ostrzegania przed pojazdami nadjeżdżającymi z tyłu i z boku, Ładowarka indukcyjna baterii telefonu w konsoli centralnej, Układ utrzymania w osi pasa ruchu, Adaptacyjne reflektory pikselowe IntelliLux LED, Podgrzewana szyba przednia, Reflektory przeciwmgielne w technologii LED, Wyświetlacz projekcyjny kierowcy Intelli-HUD, Pakiet Intelli-Drive 1.0)", "price": "9 900,00 PLN brutto", "category": "Fabryczna", "price_type": "brutto"}], "price_domain": "brutto", "transmission": "Automatyczna", "_price_domain": "brutto", "options_price": "13 100,00 PLN brutto", "vehicle_class": "Osobowy", "exterior_color": "Lakier metalizowany - czarny metalizowany 3 200,00 zł brutto", "engine_capacity": "1.5", "engine_category": "Diesel (ON)", "is_metalic_paint": true, "service_equipment": null, "engine_designation": null, "standard_equipment": ["Przednie i boczne poduszki powietrzne kierowcy i pasażera oraz kurtynowe poduszki w obu rzędach", "Układ stabilizacji toru jazdy ESP® z ABS i Traction Control oraz układem wspomagającym ruszanie na pochyłościach HSA", "Układ automatycznego hamowania po wykryciu uderzenia", "Pakiet Dobrej Widoczności", "Światłoczułe lusterko wewnętrzne (bezramkowe w GS i GSe), czujnik deszczu, automatyczne sterowanie światłami z czujnikiem oświetlenia (tunelowym)", "Zapłon sterowany przyciskiem „Start\"", "System automatycznego sterowania zamkami drzwi przednich i zapłonem Open&Start", "Zaawansowany system parkowania (panoramiczne kamery 3600 Intelli-Vision z czujnikami parkowania przód/tył)", "Elektrycznie sterowany hamulec postojowy", "Europejski Pakiet Bezpieczeństwa", "Zaawansowany układ rozpoznawania znaków z funkcją dostosowania prędkości", "Ostrzeganie przed kolizją czołową z automatycznym hamowaniem awaryjnym", "Zaawansowany układ wykrywania pieszych i rowerzystów z systemem zapobiegania kolizji i hamowania awaryjnego", "Układ utrzymania na pasie ruchu", "System wykrywania zmęczenia kierowcy", "Tempomat adaptacyjny (Stop&Go dla skrzyń automatycznych) z inteligentnym ogranicznikiem prędkości", "Kolorowy 10\" wyświetlacz graficzny wsk