INSERT INTO "public"."vehicle_synthesis" ("id", "brand", "model", "offer_number", "raw_pdf_url", "schema_version", "verification_status", "synthesis_data", "file_hash", "notes", "created_at", "zabudowa_apr_wr", "document_category", "processing_updated_at", "document_markdown") VALUES ('ff7c4964-e975-4aa4-8ed1-fd2c0ef7f98e', 'Volkswagen', 'Crafter Podwozie', NULL, 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/ff7c4964-e975-4aa4-8ed1-fd2c0ef7f98e-Cennik_Crafter_Podwozie.pdf', NULL, 'completed', '{"brand": "Volkswagen", "model": "Crafter Podwozie", "card_summary": {"drive_type": "Napęd FWD", "_validation": {"summary": {"details": "Baza + opcje = total. Wszystkie ceny w realistycznym zakresie. Brak wykrytych anomalii.", "verdict": "Ceny spójne arytmetycznie", "confidence": "HIGH", "suggestions": []}, "is_valid": true, "warnings": [], "parsed_prices": {"base": null, "total": null, "options": null}}, "_price_domain": "unknown", "suggested_discount_pct": 30, "suggested_discount_source": "Marka ''Volkswagen'' została dopasowana do ''VW Dostawcze''. Model ''Crafter Podwozie'' został dopasowany do wierszy rabatowych dla ''Crafter Podwozie z poj. kab.'' (i innych wariantów podwozia), które oferują ten sam rabat.", "suggested_discount_confidence": 90}, "digital_twin": {"pages": [{"elements": [{"type": "visual_description", "content": "Zdjęcie przedstawia niebieski samochód dostawczy Volkswagen Crafter w wersji podwozie z zabudową skrzyniową przykrytą czarną plandeką. Pojazd jest zaparkowany na placu przed nowoczesnym, przeszklonym budynkiem. Niebo jest lekko zachmurzone."}, {"type": "promo_badge", "title": "5 LAT GWARANCJI PRODUCENTA 1)", "content": "Logo z dużą cyfrą ''5'' i napisem ''LAT'' oraz ''GWARANCJI PRODUCENTA''."}, {"type": "promo_box", "title": "Pakiet przeglądów serwisowych w cenie 2)", "content": "Biały prostokątny baner z czarnym tekstem."}, {"type": "header", "level": 1, "content": "Cennik Volkswagen Crafter Podwozie"}, {"type": "metadata", "content": "Rok produkcji 2026\nRok modelowy 2026\nObowiązuje od 1.01.2026"}, {"type": "logo", "brand": "Volkswagen Samochody Dostawcze", "description": "Logo Volkswagen z napisem ''Samochody Dostawcze''."}, {"type": "footnotes", "content": [{"text": "5-letnia gwarancja fabryczna na nowe samochody: pierwsze 2 lata bez limitu km, piąty rok z maksymalnym całkowitym przebiegiem 250 000 km; 3-letnia gwarancja na powłokę lakierniczą; 12-letnia gwarancja na nieprzerdzewienie karoserii", "marker": "1)"}, {"text": "Pakiet przeglądów w standardzie: 1 wymiana oleju + 1 przegląd okresowy (bez wymiany oleju). Zakres pakietu przeglądów: wymiana oleju silnikowego, wymiana filtra oleju, przegląd bez wymiany oleju silnikowego, wymiana filtra kabinowego, wymiana płynu hamulcowego. Czynności serwisowe mogą być zrealizowane z uwzględnieniem interwału Producenta lub zgodnie z zaleceniem Partnera Serwisowego, jednak nie później, niż do czasu pierwszego przeglądu.", "marker": "2)"}]}], "page_number": 1}, {"elements": [{"type": "section", "title": "1. Modele bazowe", "content": [{"rows": [["3640", "pojedyncza", "2.0 TDI", "103/140", "6 - biegowa, manualna", "1 + 2", "152 330", "187 366"], ["3640", "pojedyncza", "2.0 TDI", "103/140", "8 - biegowa, automatyczna", "1 + 2", "163 130", "200 650"], ["3640", "pojedyncza", "2.0 TDI", "130/177", "6- biegowa, manualna", "1 + 2", "161 330", "198 436"], ["3640", "pojedyncza", "2.0 TDI", "130/177", "8 - biegowa, automatyczna", "1 + 2", "172 130", "211 720"], ["3640", "podwójna", "2.0 TDI", "103/140", "6- biegowa, manualna", "3 + 4", "159 830", "196 591"], ["3640", "podwójna", "2.0 TDI", "103/140", "8 - biegowa, automatyczna", "3 + 4", "170 630", "209 875"], ["3640", "podwójna", "2.0 TDI", "130/177", "6- biegowa, manualna", "3 + 4", "168 830", "207 661"], ["3640", "podwójna", "2.0 TDI", "130/177", "8 - biegowa, automatyczna", "3 + 4", "179 630", "220 945"], ["4490", "pojedyncza", "2.0 TDI", "103/140", "6- biegowa, manualna", "1 + 2", "1