INSERT INTO "public"."document_library" ("id", "file_name", "document_url", "document_type", "brand", "model", "valid_from", "description", "digital_twin", "created_at", "document_markdown") VALUES ('59911d9c-a324-414e-b2af-de35b06a4329', 'cennik_MY26PY26_CUPRA_Leon (1).pdf', 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/03cf7174-c40f-465b-9e9c-1af7f30ee4ab-cennik_MY26PY26_CUPRA_Leon__1_.pdf', 'OTHER', NULL, NULL, NULL, NULL, '{"brand": "CUPRA", "model": "Leon", "digital_twin": {"pages": [{"type": "cover_page", "content": [{"text": "NOWA CUPRA LEON", "type": "title"}, {"type": "visual_element", "description": "Zdjęcie przedstawia przód nowego modelu CUPRA Leon w matowym, ciemnoszarym kolorze. Samochód jest pokazany z perspektywy niskiego kąta, co podkreśla jego agresywny design. Włączone są charakterystyczne, trójkątne światła LED. Na tablicy rejestracyjnej widnieje napis ''NEW LEON''. W tle widać nowoczesne, geometryczne kształty oświetlone na czerwono i niebiesko. Na grillu znajduje się miedziane logo CUPRA."}, {"type": "text_block", "content": ["ROK MODELOWY 2026", "OBOWIĄZUJE OD: 01.12.2025", "DLA SAMOCHODÓW PRODUKOWANYCH W 2026 R."]}, {"type": "logo", "brand": "CUPRA", "description": "Logo CUPRA na dole strony."}, {"text": "5 LAT GWARANCJI CUPRA", "type": "badge", "description": "Logo 5 lat gwarancji CUPRA w prawym dolnym rogu."}], "page_number": 1}, {"type": "visual_highlights", "content": [{"type": "visual_element", "details": [{"image": "Górne lewe zdjęcie, widok na trzy czwarte z przodu.", "annotations": ["Matowy lakier Magnetic Tech Matt", "Ikoniczne światła matrix LED z trójkątną sygnaturą CUPRA"]}, {"image": "Dolne lewe zdjęcie, widok na trzy czwarte z tyłu.", "annotations": ["Zintegrowane tylne światła LED", "HAILSTORM COPPER 19-calowe kute felgi aluminiowe"]}, {"image": "Prawe zdjęcie, zbliżenie na podświetlane logo CUPRA na tylnej klapie.", "annotations": ["Podświetlane logo CUPRA"]}], "description": "Kompozycja trzech zdjęć prezentujących detale stylistyczne nowej CUPRA Leon."}], "page_number": 2}, {"type": "financing_offers", "content": [{"logo": "5 LAT GWARANCJI", "type": "header", "title": "NOWA CUPRA LEON"}, {"type": "visual_element", "description": "Dwa zdjęcia: po lewej widok na przód samochodu z tablicą ''NEW LEON SP'', po prawej zbliżenie na tylne podświetlane logo CUPRA."}, {"type": "offer_section", "title": "Leasing JAK ABONAMENT", "main_price": "od 652 zł netto / mies.", "description": "Sprawdź, w jaki sposób kwota Twojej miesięcznej raty netto może się zmienić, w zależności od poziomu wniesionej wpłaty własnej:", "pricing_details": {"rows": [{"rata": "652 zł", "wpłata własna": "30%"}, {"rata": "920 zł", "wpłata własna": "20%"}, {"rata": "1 188 zł", "wpłata własna": "10%"}, {"rata": "1 456 zł", "wpłata własna": "0%"}], "type": "table", "headers": ["wpłata własna", "rata"]}}, {"type": "offer_section", "title": "Leasing Klasyczny", "main_price": "suma opłat od 103%"}, {"text": "LEASING KLASYCZNY: Suma opłat 106% dostępna jest dla następujących parametrów leasingu: opłata wstępna: 20%, okres leasingu: 36 miesięcy, wartość wykupu: 36 miesięcy - 1%. Oferta dla przedsiębiorców.\nLeasing JAK ABONAMENT: opłata wstępna: 0-30%, okres leasingu: 48 miesięcy, roczny przebieg 10 000 km, finalna rata określona w umowie. Oferta dla przedsiębiorców.\nIlekroć mowa jest o miesięcznym koszcie elementu wyposażenia opcjonalnego rozumie się przez to zwiększenie raty miesięcznej CUPRA I CUPRA Leasing Jak Abonament wyliczonej dla przedsiębiorców, przygotowana przez Volkswagen Financial Services Polska Sp. z o.o.. Prezentowane miesięczne raty to wartość netto rat dla oferty CUPRA I CUPRA Leasing Jak Abonament. Ceny przyjęte do kalkulacji rat dostępne są w salonach. Niniejsza informacja nie stanowi oferty w rozumieniu kodeksu cywilnego. Dostępność i warunki produktu mogą ulec zmianie. Warunki produktu określa umowa. Pod nazwą CUPRA Financial Services oferowane są usługi bankowe (przez Volk