INSERT INTO "public"."document_library" ("id", "file_name", "document_url", "document_type", "brand", "model", "valid_from", "description", "digital_twin", "created_at", "document_markdown") VALUES ('6f91689c-ebad-43c9-bdeb-4b48beab8160', 'Cennik Kamiq RP26 RM26.pdf', 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/3b0391f8-f138-4bb7-9075-c7bdf121a907-Cennik_Kamiq_RP26_RM26.pdf', 'OTHER', NULL, NULL, NULL, NULL, '{"brand": "Škoda", "model": "Kamiq", "digital_twin": {"pages": [{"elements": [{"type": "title", "content": "Nowa Škoda Kamiq"}, {"type": "text", "content": "Rok Produkcji 2026\nRok Modelowy 2026"}, {"type": "image", "description": "Pomarańczowa Škoda Kamiq jadąca ulicą miasta. W tle widać kawiarniane ogródki z parasolami. Na tablicy rejestracyjnej widnieje numer PY 2952H."}, {"type": "logo", "brand": "SKODA"}, {"type": "qr_code", "content": "Zobacz Škodę Kamiq w akcji - obejrzyj nasz test"}, {"type": "promotion", "content": "Wersja Drive z sumą korzyści do 7 900 zł 2"}, {"type": "text", "content": "3 lata gwarancji"}], "page_number": 1}, {"elements": [{"type": "section_title", "content": "Nowa oferta finansowania"}, {"type": "title", "content": "Czas na relaks ze Škoda Najem All Inclusive"}, {"type": "image", "description": "Widok na tył białej Škody Kamiq. Obok samochodu stoi kobieta w zielonej sukience. W tle widać drzewo oliwne."}, {"type": "list", "items": ["Ubezpieczenie AC/OC", "Pełna obsługa serwisowa", "Opony letnie i zimowe z wymianą i przechowaniem", "Całodobowe wsparcie Assistance", "Samochód zastępczy bez limitu", "Stała miesięczna opłata", "Możliwość wymiany auta już po 12 miesiącach", "Odliczenie podatku VAT i rozliczenie kosztu najmu"], "title": "Rata zawiera:"}, {"type": "call_to_action", "content": "Poznaj ofertę na skodanajem.pl"}, {"type": "footnote", "content": "*dotyczy osób prowadzących działalność gospodarczą.\nPod nazwą Volkswagen Financial Services oferowane są usługi bankowe (przez Volkswagen Bank GmbH Sp. z o.o. Oddział w Polsce), usługi leasingowe i mobilność (przez Volkswagen Financial Services Polska Sp. z o.o.) oraz usługi ubezpieczeniowe (przez Volkswagen Serwis Ubezpieczeniowy Sp. z o.o. jako agenta ubezpieczeniowego)."}], "page_number": 2}, {"elements": [{"type": "title", "content": "Odkryj nową Škodę Kamiq"}, {"type": "feature_grid", "columns": [{"items": [{"title": "Bezpieczeństwo pieszych", "description": "Front Assist - kontrola odstępu z funkcją awaryjnego hamowania z Pedestrian Monitor", "image_description": "Widok z góry na czerwoną Škodę Kamiq, która hamuje przed pieszym. System Front Assist jest zwizualizowany."}, {"title": "Bezpieczeństwo pasywne", "description": "Nawet do 9 poduszek bezpieczeństwa", "image_description": "Przekrój samochodu z widocznymi poduszkami powietrznymi."}, {"title": "Bezpieczeństwo aktywne", "description": "Pakiety Assisted Drive zawierają m.in. Adaptive Lane Assist, Side Assist i Adaptive Cruise Control", "image_description": "Dwa samochody na drodze z wizualizacją działania systemów asystujących."}], "title": "Bezpieczeństwo"}, {"items": [{"title": "Dach panoramiczny", "description": "Doświetla wnętrze samochodu i optycznie zwiększa jego przestrzeń.", "image_description": "Widok z wnętrza pojazdu na panoramiczny dach."}, {"title": "Reflektory Full LED Matrix", "description": "Zwiększają komfort i bezpieczeństwo po zmroku", "image_description": "Zbliżenie na przedni reflektor Full LED Matrix."}, {"title": "Oświetlenie LED Ambiente", "description": "Pozwala na łatwą i ciekawą personalizację wnętrza", "image_description": "Fragment deski rozdzielczej z podświetleniem ambientowym."}], "title": "Design"}, {"items": [{"title": "Wyświetlacz Infotainment z nawigacją 9,2\"", "description": "Nowoczesne systemy infotainment z funkcją SmartLink pozwalają na bezprzewodowe połączenie ze smartfonem*", "image_description": "Ekran systemu Infotainment z widocznym menu głównym."}, {"title": "Gniazda USB-C", "description": "Cztery nowoczesne gniazda USB-C do szybkiego ładowania o mocy aż 45W oraz Phone Box o mocy 15 W", "image_description": "Smartfon ładowany bezprzewodowo w schowku Phone Box."}, {"title": "Przemyślana technologia", "description": "Bezdotykowe otwieranie i zamykanie elektrycznie sterowanej pokrywy bagażnika", "image_description": "Biała Škoda Kamiq z otwartą elektrycznie pokrywą bagażnika."}], "title": "Nowe technologie"}]}, {"type": "footnote", "content": "Niektóre z prezentowanych elementów stanowią wyposażenie opcjonalne. Szczegóły w dalszej części cennika oraz u sprzedawców. Systemy wspierające kierowcę działają w granicach możliwości technologicznych, dlatego nadal niezbędne jest zachowanie ostrożności przez kierowcę. Kierowca musi być w każdej chwili gotowy do przejęcia kontroli nad pojazdem. Systemy wspomagające nie zwalniają go z odpowiedzialności za zachowanie szczególnej ostrożności.\n* SmartLink oferuje możliwość obsługi i wyświetlania na ekranie systemu Infotainment certyfikowanych aplikacji (poprzez Android Auto lub Apple CarPlay) zainstalowanych na smartfonie podłączonym za pomocą przewodu USB (dla urządzeń z systemem Android i Apple iOS) lub bezprzewodowo (dla urządzeń z systemem Apple iOS). Działanie SmartLink uzależnione jest od wersji oprogramowania i modelu smartfona. Więcej informacji można uzyskać na stronie https://compatibilitylist.skoda-auto.com"}], "page_number": 3}, {"elements": [{"type": "title", "content": "Ceny i wersje wyposażenia Škoda Kamiq"}, {"type": "pricing_table", "description": "Tabela cenowa dla różnych wersji silnikowych i wyposażenia.", "table_markdown": "| Silnik | Moc | Skrzynia biegów | Essence | Najniższa cena Essence | Selection | Najniższa cena Selection | Drive | Najniższa cena Drive | Monte Carlo | Najniższa cena Monte Carlo |\n|---|---|---|---|---|---|---|---|---|---|---|\n| 1.0 TSI | 70 kW (95KM) | manualna, 5-biegowa | 88 300 zł ~~92 300 zł~~ | 92 300 zł | 99 500 zł ~~104 550 zł~~ | 104 550 zł | 101 250 zł ~~107 250 zł~~ | 107 250 zł | - | - |\n| 1.0 TSI | 85 kW (115 KM) | manualna, 6-biegowa | 92 550 zł ~~96 550 zł~~ | 96 550 zł | 103 800 zł ~~108 800 zł~~ | 108 800 zł | 105 500 zł ~~111 500 zł~~ | 111 500 zł | 114 050 zł ~~120 050 zł~~ | 120 050 zł |\n| 1.0 TSI | 85 kW (115 KM) | automatyczna, 7-biegowa DSG | 99 100 zł ~~103 100 zł~~ | 103 100 zł | 110 550 zł ~~115 550 zł~~ | 115 550 zł | 112 250 zł ~~118 250 zł~~ | 118 250 zł | 120 850 zł ~~126 850 zł~~ | 126 850 zł |\n| 1.5 TSI | 110 kW (150 KM) | manualna, 6-biegowa | - | - | 112 450 zł ~~117 450 zł~~ | 117 450 zł | 114 150 zł ~~120 150 zł~~ | 120 150 zł | 122 750 zł ~~128 750 zł~~ | 128 750 zł |\n| 1.5 TSI | 110 kW (150 KM) | automatyczna, 7-biegowa DSG | - | - | 117 200 zł ~~122 200 zł~~ | 122 200 zł | 118 900 zł ~~124 900 zł~~ | 124 900 zł | 127 550 zł ~~133 550 zł~~ | 133 550 zł |"}, {"type": "image", "description": "Biała Škoda Kamiq zaparkowana na podjeździe."}, {"type": "promotion", "title": "SKODA LPG", "content": "Instalacja LPG Landi RENZO zaprojektowana dla wybranych silników TSI. O szczegóły zapytaj sprzedawcę³"}], "page_number": 4}, {"elements": [{"type": "title", "content": "Škoda Kamiq Drive"}, {"type": "image", "description": "Główne zdjęcie przedstawia pomarańczową Škodę Kamiq na ulicy miejskiej, tablica rejestracyjna 4ST 5813. Poniżej dwa mniejsze zdjęcia wnętrza: jedno pokazuje przednie fotele, drugie deskę rozdzielczą i kierownicę."}, {"type": "list", "items": ["Przednie reflektory przeciwmgłowe z funkcją CORNER", "Tylne światła Full LED z dynamicznymi kierunkowskazami", "2 - ramienna kierownica wielofunkcyjna podgrzewana", "Podgrzewane przednie fotele", "Elektrycznie ogrzewana przednia szyba", "Gniazdo USB-C w podstawie lusterka", "Elektrycznie składane lusterka boczne (lusterko boczne po stronie kierowcy - przyciemniane)", "Light and Rain Assist – czujnik zmierzchu i deszczu"], "title": "Standard wersji Selection i dodatkowo:"}], "page_number": 5}, {"elements": [{"type": "title", "content": "Wybrane wyposażen