ices": {"items": [{"name": "Serwisowy Kontrakt Flotowy", "benefits": ["Jednolita forma obsługi", "Bezgotówkowa forma rozliczeń", "Oszczędność czasu"]}, {"name": "Oryginalne akcesoria", "benefits": ["Spełniają najwyższe wymagania marki", "Sprostają wszystkim Twoim potrzebom", "Wysoka jakość wykonania i komfort użytkowania"]}, {"name": "Możliwość rozszerzenia zakresu usług Pakietów Przeglądów Serwisowych", "benefits": ["Stałość i przewidywalność kosztów", "Komfort i bezpieczeństwo", "Wyższa wartość samochodu"]}], "title": "DODATKOWE USŁUGI: Twój wybór! Zapytaj sprzedawcę."}}, "additional_elements_summary": {"sum": "0,00 PLN netto", "title": "ELEMENTY DODATKOWE"}}, "offer_number": "GON-26-0020245", "configuration_code": "SYBB4A\\EB9\\NZ4\\QE4\\R22\\WF9\\ZA3\\ZR8\\Z65\\2JF\\2NB\\3R2\\3SS\\6N1\\6XN\\7C3\\9WJ", "_extraction_metadata": {"model": "gemini-2.5-pro", "stage": "digital_twin", "output_tokens": 10384, "prompt_tokens": 4758, "thinking_tokens": 5072}}'::jsonb, '2026-03-12T07:56:01.958615+00:00', NULL);
