INSERT INTO "public"."document_library" ("id", "file_name", "document_url", "document_type", "brand", "model", "valid_from", "description", "digital_twin", "created_at", "document_markdown") VALUES ('bb25b05e-340b-43ea-8394-917cf51ed579', 'cennik_MY24PY24_CUPRA_Tavascan.pdf', 'https://gnpsdiarmwvqhqbyetce.supabase.co/storage/v1/object/public/raw-vehicle-pdfs/d96e1baa-8030-4198-aa56-2f737e94ba6c-cennik_MY24PY24_CUPRA_Tavascan.pdf', 'OTHER', NULL, NULL, NULL, NULL, '{"brand": "CUPRA", "model": "Tavascan", "digital_twin": {"pages": [{"type": "Cover Page", "content": [{"text": "NOWA CUPRA TAVASCAN", "type": "title"}, {"text": "ROK MODELOWY 2024\nOBOWIĄZUJE OD: 05.08.2025 r.\nDLA SAMOCHODÓW PRODUKOWANYCH W 2024 r.", "type": "metadata"}, {"type": "logo", "description": "Logo ''5 CUPRA LAT GWARANCJI''"}], "visuals": [{"type": "image", "description": "Zbliżenie na maskę i przedni reflektor nowej Cupry Tavascan w kolorze ciemnoniebieskim. Widoczne jest miedziane logo CUPRA na masce oraz napis CUPRA pod krawędzią maski. Na tablicy rejestracyjnej widoczny jest fragment napisu ''2400''."}], "page_number": 1}, {"type": "Design Highlights", "content": [{"text": "NOWA CUPRA TAVASCAN", "type": "title"}, {"text": "NOWY KIERUNEK STYLISTYCZNY I WYJĄTKOWY DESIGN MARKI CUPRA", "type": "subtitle"}], "visuals": [{"type": "image_gallery", "images": [{"callout": "Podświetlane logo CUPRA", "description": "Zbliżenie na podświetlane, miedziane logo CUPRA na masce samochodu."}, {"callout": "Ikoniczne światła matrix LED z trójkątną sygnaturą CUPRA", "description": "Przednia, trzy-czwarta perspektywa szarej Cupry Tavascan, podkreślająca charakterystyczne światła."}, {"callout": "KATLA 21-calowe kute felgi aluminiowe", "description": "Zbliżenie na tylne koło i fragment nadwozia szarej Cupry Tavascan."}]}], "page_number": 2}, {"type": "Financing Options", "content": [{"text": "NOWA CUPRA TAVASCAN", "type": "title"}, {"text": "WYBIERZ FORMĘ FINANSOWANIA DOSTOSOWANĄ DO TWOICH POTRZEB", "type": "subtitle"}, {"name": "Leasing JAK ABONAMENT", "type": "financing_option", "price": "Rata od: 1013 zł netto", "details": ["Opłata wstępna 0-30%", "Okres finansowania 36-48 miesięcy", "Za tą część nie płacisz"], "description": "Chcesz mieć niższe raty niż w tradycyjnym leasingu. W tym produkcie spłacasz jedynie prognozowaną utratę wartości auta podczas jego użytkowania, a nie jego całą wartość"}, {"name": "Najem", "type": "financing_option", "price": "Rata od: 1725 zł netto", "details": ["Opłata wstępna 0-30%", "Czas trwania umowy 36-48 miesięcy", "Koniec umowy – zwracasz auto"], "description": "Cenisz sobie wygodę i chcesz mieć wszystko w jednej miesięcznej opłacie (ubezpieczenie, assistance, auto zastępcze, serwis czy i zarządzanie szkodami)"}, {"text": "Leasing JAK ABONAMENT: Przykładowa opłata miesięczna: wpłata wstępna w wysokości 30.000 netto (możliwa refundacja w ramach programu NaszEauto), okres leasingu: 36 miesięcy, roczny przebieg 10.000 km., cena samochodu 244.168 zł. Oferta dla przedsiębiorców.\nNajem:. Przykładowa opłata miesięczna: wpłata wstępna w wysokości 30.000 netto (możliwa refundacja w ramach programu NaszEauto), okres najmu: 36 miesięcy, roczny przebieg 10 000 km. cena samochodu 244.168 zł. Oferta dla przedsiębiorców. Oferta do wyczerpania zapasów magazynowych.\nPowyższe informacje nie stanowią oferty w rozumieniu kodeksu cywilnego. Dostępność i warunki produktu mogą ulec zmianie. Warunki produktu określa umowa.\n*Szczegóły dotyczące programu NaszEauto na stronie https://www.gov.pl/web/nfosigw/e11-wzrost-wykorzystania-transportu-przyjaznego-dla-srodowiska-program-priorytetowy-naszeauto#_ftn5", "type": "disclaimer"}], "visuals": [{"type": "image", "description": "Dwa samochody Cupra Tavascan, biały i ciemny, na tle wnętrza samochodu, ilustrujące opcje finansowania."}], "page_number": 3}, {"type": "Pricing with Subsidy", "content": [{"text": "NOWA CUPRA TAVASCAN", "type": "title"}, {"text": "CENNIK PRZY ZAKUPIE W PROGRAMIE „NaszEauto” Z DOPŁATĄ 30 000 ZŁ", "type": "subtitle"}, {"rows": [{"Moc": "210 kW / 286 KM 2)", "Wersja": "Cupra Tavascan Endurance + lakier metalik", "Skrzynia biegów": "automatyczna 1-stopniowa", "Pojemność akumulatora": "77 kWh", "Cena brutto z subwencją „NaszEauto”*": "214 168 zł 1)"}], "type": "pricing_table", "header": ["Wersja", "Moc", "Pojemność akumulatora", "Skrzynia biegów", "Cena brutto z subwencją „NaszEauto”*"]}, {"type": "footnotes", "items": ["*Cena uwzględnieniu dopłaty beneficjentów programu NaszEauto w wysokości 30 000 zł. Szczegółowe warunki programu dostępne są na stronie NFOŚiGW: https://www.gov.pl/web/nfosigw/e11-wzrost-wykorzystania-transportu-przyjaznego-dla-srodowiska-program-priorytetowy-naszeauto#_ftn5", "1) Cena uwzględnienia dopłatę za lakier metalik. Tylko oferta magazynowa do wyczerpania zapasów.", "2) Moc dostępna w danej sytuacji na drodze zależy od zmiennych czynników, takich jak temperatura zewnętrzna, temperatura, stan ładowania i kondycjonowania lub fizyczne starzenie się akumulatora wysokonapięciowego. Dostępność maksymalnej mocy wymaga w szczególności temperatury akumulatora wysokonapięciowego w zakresie od 23 do 50 °C i poziomu naładowania akumulatora > 88%. Odchylenia w szczególności od wyżej wymienionych parametrów mogą prowadzić do zmniejszenia wydajności lub nawet nieosiągnięcia maksymalnej wydajności. Funkcja klimatyzacji postojowej może w pewnym stopniu wpływać pośrednio na temperaturę akumulatora, a także regulować stan naładowania akumulatora w pojeździe. Aktualnie dostępna moc jest wyświetlana na wyświetlaczu przebiegu pojazdu. Aby jak najlepiej zachować użyteczną pojemność akumulatora wysokonapięciowego, zaleca się ustawienie docelowego poziomu ładowania akumulatora do codziennego użytku na poziomie 80% (na przykład ustawienie go na 100%) w przypadku podróży na duże odległości."]}], "visuals": [{"type": "image", "description": "Szara Cupra Tavascan zaparkowana przy wodzie o zmierzchu. Po prawej stronie widok na wnętrze pojazdu, w tym kierownicę i deskę rozdzielczą."}], "page_number": 4}, {"type": "Subsidy Program Details", "content": [{"text": "NOWA CUPRA TAVASCAN", "type": "title"}, {"text": "„PROGRAM NaszEauto”", "type": "subtitle"}, {"text": "Program NaszEauto – dofinansowanie zakupu, leasingu lub najmu samochodów elektrycznych", "type": "section_title"}, {"text": "Jeśli jesteś osobą fizyczną lub osobą fizyczną wykonującą działalność gospodarczą możesz zakupić Tavascana z dotacją Programu NaszEauto w wysokości maksymalnie do 40.000 PLN. Możliwość uzyskania dotacji zależy od maksymalnej ceny samochodu netto w wysokości 225.000 zł (276 750 brutto)", "type": "paragraph"}, {"type": "table_markdown", "table": "| Kategoria | Bazowa kwota wsparcia | Premia za zezłomowanie | Premia za niski dochód | Maksymalna kwota wsparcia |\n|---|---|---|---|---|\n| Osoby fizyczne (zakup) | 18 750 PLN | 10 000 PLN | 11 250 PLN | 40 000 PLN |\n| Osoby fizyczne z kartą dużej rodziny (zakup) | 30 000 PLN | 5 000 PLN | 5 000 PLN | 40 000 PLN |\n| Osoby fizyczne (leasing, wynajem) | do 30 000 PLN | 5 000 PLN | 5 000 PLN | 40 000 PLN |\n| Jednoosobowe działalności gospodarcze (zakup) | 30 000 PLN | 10 000 PLN | | 40 000 PLN |\n| Jednoosobowe działalności gospodarcze (leasing, wynajem) | do 30 000 PLN | 10 000 PLN | | 40 000 PLN |"}, {"text": "*Szczegóły na stronie https://www.gov.pl/web/nfosigw/e11-wzrost-wykorzystania-transportu-przyjaznego-dla-srodowiska-program-priorytetowy-naszeauto#_ftn5", "type": "footnote"}], "visuals": [{"type": "image", "description": "Szara Cupra Tavascan na drodze, widok z góry."}], "page_number": 5}, {"type": "Standard Pricing", "content": [{"text": "NOWA CUPRA TAVASCAN", "type": "title"}, {"rows": [{"Moc": "210 kW / 286 KM 3)", "Wersja": "Cupra Tavascan Endurance + lakier metalik", "Cena brutto": "244 168 zł¹)", "Skrzynia biegów": "automatyczna 1-stopniowa", "Pojemność akumulatora": "77 kWh"}, {"Moc": "250 kW / 340 KM 3)", "Wersja": "Cupra Tavascan VZ 4Drive +Pakiet Adrenaline i Pakiet zimowy", "Cena 